INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('itmeGirish/BoardingMcp-Server/prayer-agent', 'community', 'itmeGirish', 'BoardingMcp-Server', 'itmeGirish/BoardingMcp-Server', 'prayer-agent', 0, 0, 33, '2026-02-25T16:04:12Z', '2026-03-02T09:42:57.133Z', '066e217b6c9fcb73b9ca6d26fa22701d7960c893c112d036b1b73345f84e5812', '{"id":"itmeGirish/BoardingMcp-Server/prayer-agent","name":"prayer-agent","description":{"zh":"Prayer Agent是一个MCP服务器，为Whatsp API提供AI智能代理功能","ja":"Prayer Agentは、MCPサーバーを使用してWhatsp APIのAIエージェント機能を提供するツールです","ko":"Prayer Agent는 MCP 서버를 사용하여 Whatsp API의 AI 에이전트 기능을 제공하는 솔루션입니다","es":"El agente de oración es un servidor MCP para la API de WhatsApp, diseñado para facilitar la integración","fr":"L''agent de prière est un serveur MCP pour l''API WhatsApp, conçu pour faciliter l''intégration","de":"Der Gebetsagent ist ein MCP-Server für die WhatsApp-API, entwickelt zur Vereinfachung der Integration","pt":"O Agente de Oração é um servidor MCP para a API do WhatsApp, permitindo a integração de funcionalidades de oração em suas aplicações","ru":"ИИ Агент для Молитвы - это сервер MCP для WhatsApp API, позволяющий интегрировать функции молитвы в ваши приложения","ar":"وكيل الصلاة هو خادم MCP ل API واتساب، يسمح بدمج وظائف الصلاة في تطبيقاتك","en":"It is mcp server for the whatsp api"},"seo":{"title":{"zh":"AI智能代理工具 - Prayer Agent","ja":"AIエージェントプラグイン - Prayer Agent","ko":"AI 에이전트 솔루션 - Prayer Agent","es":"Agente de oración: Servidor MCP para WhatsApp API","fr":"Agent de prière: Serveur MCP pour l''API WhatsApp","de":"Gebetsagent: MCP-Server für WhatsApp-API","pt":"Agente de Oração: MCP Server para WhatsApp API","ru":"ИИ Агент для Молитвы: MCP Server для WhatsApp API","ar":"وكيل الصلاة: خادم MCP ل API واتساب","en":"prayer-agent"},"description":{"zh":"Prayer Agent是一个MCP服务器，为Whatsp API提供AI智能代理功能","ja":"Prayer Agentは、MCPサーバーを使用してWhatsp APIのAIエージェント機能を提供するツールです","ko":"Prayer Agent는 MCP 서버를 사용하여 Whatsp API의 AI 에이전트 기능을 제공하는 솔루션입니다","es":"El agente de oración es un servidor MCP para la API de WhatsApp, diseñado para facilitar la integración","fr":"L''agent de prière est un serveur MCP pour l''API WhatsApp, conçu pour faciliter l''intégration","de":"Der Gebetsagent ist ein MCP-Server für die WhatsApp-API, entwickelt zur Vereinfachung der Integration","pt":"O Agente de Oração é um servidor MCP para a API do WhatsApp, permitindo a integração de funcionalidades de oração em suas aplicações","ru":"ИИ Агент для Молитвы - это сервер MCP для WhatsApp API, позволяющий интегрировать функции молитвы в ваши приложения","ar":"وكيل الصلاة هو خادم MCP ل API واتساب، يسمح بدمج وظائف الصلاة في تطبيقاتك","en":"It is mcp server for the whatsp api"},"definition":{"en":"It is mcp server for the whatsp api"},"features":{"zh":["支持MCP服务器","集成Whatsp API","提供AI智能代理功能","简单易用的API接口","高性能和可扩展性"],"ja":["MCPサーバーのサポート","Whatsp APIの統合","AIエージェント機能の提供","シンプルで使いやすいAPIインターフェース","高パフォーマンスとスケーラビリティ"],"ko":["MCP 서버 지원","Whatsp API 통합","AI 에이전트 기능 제공","간단하고 사용하기 쉬운 API 인터페이스","고성능과 확장성"],"es":["Servidor MCP para la API de WhatsApp","Integración simplificada","Compatibilidad con múltiples plataformas","Soporte técnico especializado","Documentación detallada"],"fr":["Serveur MCP pour l''API WhatsApp","Intégration simplifiée","Compatibilité avec plusieurs plateformes","Support technique spécialisé","Documentation détaillée"],"de":["MCP-Server für die WhatsApp-API","Vereinfachte Integration","Kompatibilität mit mehreren Plattformen","Spezialisiertes technisches Support","Detaillierte Dokumentation"],"pt":["Integração com WhatsApp API","Servidor MCP para funcionalidades de oração","Desenvolvimento de aplicações personalizadas","Suporte a múltiplos protocolos de comunicação","Segurança e autenticação avançadas"],"ru":["Интеграция с WhatsApp API","Сервер MCP для функций молитвы","Разработка пользовательских приложений","Поддержка нескольких протоколов связи","Продвинутая безопасность и аутентификация"],"ar":["دمج API واتساب","خادم MCP لوظائف الصلاة","تطوير تطبيقات مخصصة","دعم بروتوكولات اتصال متعددة","أمان وتحقق متقدم"]},"keywords":{"zh":["AI智能代理","MCP服务器","Whatsp API","AI工具","如何使用Prayer Agent","Prayer Agent安装","Prayer Agent替代品"],"ja":["AIエージェント","MCPサーバー","Whatsp API","AIツール","Prayer Agentの使い方","Prayer Agentのインストール","Prayer Agentの代替"],"ko":["AI 에이전트","MCP 서버","Whatsp API","AI 도구","Prayer Agent 사용법","Prayer Agent 설치","Prayer Agent 대체"],"es":["agente de oración","servidor MCP","API de WhatsApp","integración de WhatsApp","cómo usar agente de oración","agente de oración alternativa","agente de oración vs competidores","instalación de agente de oración","guía de configuración de agente de oración"],"fr":["agent de prière","serveur MCP","API WhatsApp","intégration de WhatsApp","comment utiliser l''agent de prière","alternative à l''agent de prière","agent de prière vs concurrents","installation de l''agent de prière","guide de configuration de l''agent de prière"],"de":["Gebetsagent","MCP-Server","WhatsApp-API","WhatsApp-Integration","wie man Gebetsagent verwendet","Gebetsagent-Alternative","Gebetsagent vs Wettbewerber","Installation von Gebetsagent","Konfigurationsanleitung für Gebetsagent"],"pt":["como usar agente de oração","o que é agente de oração","agente de oração alternative","agente de oração vs outros","instalar agente de oração","guia de configuração do agente de oração","desenvolvimento de aplicações com agente de oração","integração com whatsapp api"],"ru":["как использовать ИИ Агент для Молитвы","что такое ИИ Агент для Молитвы","ИИ Агент для Молитвы alternative","ИИ Агент для Молитвы vs другие","установка ИИ Агента для Молитвы","руководство по настройке ИИ Агента для Молитвы","разработка приложений с ИИ Агентом для Молитвы","интеграция с WhatsApp API"],"ar":["كيفية استخدام وكيل الصلاة","ما هو وكيل الصلاة","وكيل الصلاة بديل","وكيل الصلاة مقابل الآخرين","تثبيت وكيل الصلاة","دليل إعداد وكيل الصلاة","تطوير التطبيقات مع وكيل الصلاة","دمج API واتساب"]}},"owner":"itmeGirish","repo":"BoardingMcp-Server","repoPath":"itmeGirish/BoardingMcp-Server","stars":0,"forks":0,"updatedAt":"2026-02-25T16:04:12Z","topics":[],"category":"community","skillMd":{"name":"prayer-agent","description":"Generates correct prayers/reliefs (primary, alternative, interim) based on doc_type and issues.","bodyPreview":"# Prayer Agent\n\n## Goal\nGenerate PRAYER_PACK.json.\n\n## HARD RULES\n- Prayer must match doc_type.\n- Do not request illegal relief.\n- Always include \"such other orders\" clause.\n\n## OUTPUT CONTRACT (STRICT JSON ONLY)\nReturn ONLY:\n\n{\n  \"doc_type\": \"string\",\n  \"reliefs_primary\": [],\n  \"reliefs_alternative\": [],\n  \"interim_reliefs\": [],\n  \"costs_interest_clause\": \"string\"\n}\n\n## PRAYER STANDARDS\n- Use formal court language.\n- Use \"this Hon''ble Court\" phrasing.\n- Avoid aggressive accusations unless facts","body":"# Prayer Agent\n\n## Goal\nGenerate PRAYER_PACK.json.\n\n## HARD RULES\n- Prayer must match doc_type.\n- Do not request illegal relief.\n- Always include \"such other orders\" clause.\n\n## OUTPUT CONTRACT (STRICT JSON ONLY)\nReturn ONLY:\n\n{\n  \"doc_type\": \"string\",\n  \"reliefs_primary\": [],\n  \"reliefs_alternative\": [],\n  \"interim_reliefs\": [],\n  \"costs_interest_clause\": \"string\"\n}\n\n## PRAYER STANDARDS\n- Use formal court language.\n- Use \"this Hon''ble Court\" phrasing.\n- Avoid aggressive accusations unless facts support.\n"},"lastSynced":"2026-03-02T09:42:57.133Z","agentAnalysis":{"suitability":{"en":"Ideal for Legal AI Agents requiring structured prayer generation in JSON format.","zh":"适合需要在JSON格式中生成结构化祷文的法律AI代理。","ja":"JSON形式で構造化された祈祷文を生成する必要がある法的AIエージェントに適しています。","ko":"JSON 형식의 구조화된 기도를 생성해야 하는 법적 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA jurídicos que requieren generación de plegarias estructuradas en formato JSON.","fr":"Idéal pour les agents d''IA juridiques nécessitant une génération de prières structurées au format JSON.","de":"Ideal für juristische KI-Agenten, die eine strukturierte Gebetsgenerierung im JSON-Format erfordern.","pt":"Ideal para Agentes de IA Jurídicos que exigem geração de oração estruturada no formato JSON.","ru":"Идеально для юридических агентов ИИ, требующих структурированного поколения молитвы в формате JSON.","ar":"مثالي للوكلاء القانونيين لاستخبارات الاصطناعية الذين يحتاجون إلى توليد صلاة منظم في تنسيق JSON."},"recommendation":{"en":"Empowers agents to generate PRAYER_PACK.json files with strict adherence to doc_type, reliefs, and costs_interest_clause, utilizing formal court language and protocols like MCP server for WhatsApp API. It provides a standardized output contract with JSON-only responses, ensuring compliance with prayer standards and hard rules.","zh":"赋予代理生成PRAYER_PACK.json文件的能力，严格遵守doc_type、reliefs和costs_interest_clause，使用正式的法庭语言和协议，如MCP服务器用于WhatsApp API。它提供了标准化的输出合同，仅以JSON格式响应，确保遵守祈祷标准和硬性规则。","ja":"PRAYER_PACK.jsonファイルを生成するエージェントの能力を付与し、doc_type、reliefs、costs_interest_clauseに厳密に従い、MCPサーバーを使用したWhatsApp APIのような正式な法廷言語とプロトコルを使用します。JSONのみのレスポンスで標準化された出力契約を提供し、祈祷の基準とハードルールへの準拠を保証します。","ko":"PRAYER_PACK.json 파일을 생성하는 에이전트의 능력을 부여하며, doc_type, reliefs, costs_interest_clause를 엄격히 준수하고, MCP 서버를 사용한 WhatsApp API와 같은 공식 법정 언어와 프로토콜을 사용합니다. JSON만의 응답으로 표준화된 출력 계약을 제공하여 기도의 표준과 하드 규칙을 준수합니다.","es":"Habilita a los agentes a generar archivos PRAYER_PACK.json con estricta adherencia a doc_type, reliefs y costs_interest_clause, utilizando lenguaje y protocolos formales de tribunal como MCP server para WhatsApp API. Proporciona un contrato de salida estandarizado con respuestas solo en JSON, garantizando el cumplimiento de los estándares de plegarias y reglas estrictas.","fr":"Permet aux agents de générer des fichiers PRAYER_PACK.json avec une stricte adhésion à doc_type, reliefs et costs_interest_clause, en utilisant un langage et des protocoles formels de tribunal comme MCP server pour WhatsApp API. Fournit un contrat de sortie standardisé avec des réponses uniquement en JSON, garantissant le respect des normes de prières et des règles strictes.","de":"Ermächtigt Agenten, PRAYER_PACK.json-Dateien mit strenger Einhaltung von doc_type, reliefs und costs_interest_clause zu generieren, unter Verwendung formaler Gerichtssprache und -protokolle wie MCP-Server für WhatsApp API. Bietet einen standardisierten Ausgabevertrag mit JSON-only-Antworten, der die Einhaltung von Gebetsstandards und harten Regeln gewährleistet.","pt":"Habilita os agentes a gerar arquivos PRAYER_PACK.json com adesão estrita ao doc_type, auxílios e cláusulas de custos e juros, utilizando linguagem formal de tribunal e protocolos como servidor MCP para WhatsApp API. Ele fornece um contrato de saída padronizado com respostas apenas em JSON, garantindo conformidade com os padrões de oração e regras rígidas.","ru":"Наделяет агентов возможностью генерировать файлы PRAYER_PACK.json с строгим соблюдением doc_type, облегчений и пунктов о затратах и процентах, используя формальный язык суда и протоколы, такие как сервер MCP для WhatsApp API. Он обеспечивает стандартизированный вывод контракта с ответами только в формате JSON, гарантируя соответствие стандартам молитвы и жестким правилам.","ar":"يُمكّن الوكلاء من توليد ملفات PRAYER_PACK.json مع اتباع صارم لنوع المستند والتنازلاتات وشروط التكاليف والفوائد، باستخدام لغة رسمية للمحكمة وبروتوكولات مثل خادم MCP ل WhatsApp API. كما يوفر عقد إخراج معياريًا مع استجابات JSON فقط، مما يضمن امتثال لمعايير الصلاة والقواعد الصارمة."},"useCases":{"en":["Generating prayer packs for legal documents","Automating relief requests with alternative and interim reliefs","Creating standardized costs and interest clauses for court filings"],"zh":["为法律文件生成祈祷包","使用替代和临时救济来自动化救济请求","为法庭提交创建标准化的费用和利息条款"],"ja":["法的文書向けの祈祷パックを生成する","代替および臨時救済を使用して救済リクエストを自動化する","法廷提出用の標準化された費用および利息条項を作成する"],"ko":["법적 문서를 위한 기도 패키지를 생성하는 것","대체 및 임시 구제를 사용하여 구제 요청을 자동화하는 것","법원 제출을 위한 표준화된 비용 및 이자 조항을 생성하는 것"],"es":["Generar paquetes de plegarias para documentos jurídicos","Automatizar solicitudes de alivio con alivios alternativos e interinos","Crear cláusulas de costos e intereses estandarizadas para presentaciones judiciales"],"fr":["Générer des packs de prières pour des documents juridiques","Automatiser les demandes de secours avec des secours alternatifs et intérimaires","Créer des clauses de coûts et d''intérêts standardisées pour les dépôts judiciaires"],"de":["Generieren von Gebetspaketen für juristische Dokumente","Automatisieren von Entlastungsanfragen mit alternativen und vorläufigen Erleichterungen","Erstellen standardisierter Kosten- und Zinsklauseln für Gerichtseinreichungen"],"pt":["Geração de pacotes de oração para documentos legais","Automatização de solicitações de auxílio com auxílios alternativos e intermediários","Criação de cláusulas de custos e juros padronizadas para petições judiciais"],"ru":["Генерация пакетов молитвы для юридических документов","Автоматизация запросов на облегчение с альтернативными и промежуточными облегчениями","Создание стандартизированных пунктов о затратах и процентах для судебных исков"],"ar":["توليد حزم صلاة لمستندات قانونية","تأهيل طلبات العون ببدائل ووسائط","إنشاء شروط تكاليف وفوائد معيارية للتقديمات القضائية"]},"limitations":{"en":["Requires adherence to hard rules and prayer standards","Limited to generating PRAYER_PACK.json files in strict JSON format","Must use formal court language and avoid aggressive accusations"],"zh":["需要遵守硬性规则和祈祷标准","仅限生成严格的JSON格式的PRAYER_PACK.json文件","必须使用正式的法庭语言并避免激进的指控"],"ja":["ハードルールと祈祷の基準に従う必要がある","厳密なJSON形式のPRAYER_PACK.jsonファイルのみを生成する","正式な法廷言語を使用し、激進的な告発を避ける必要がある"],"ko":["하드 규칙과 기도의 표준을 준수해야 함","严格한 JSON 형식의 PRAYER_PACK.json 파일만 생성함","공식 법정 언어를 사용하고 공격적인 고소를 피해야 함"],"es":["Requiere adherencia a reglas estrictas y estándares de plegarias","Limitado a la generación de archivos PRAYER_PACK.json en formato JSON estricto","Debe utilizar lenguaje formal de tribunal y evitar acusaciones agresivas"],"fr":["Nécessite une adhésion aux règles strictes et aux normes de prières","Limité à la génération de fichiers PRAYER_PACK.json au format JSON strict","Doit utiliser un langage formel de tribunal et éviter les accusations agressives"],"de":["Erfordert die Einhaltung von harten Regeln und Gebetsstandards","Begrenzt auf die Generierung von PRAYER_PACK.json-Dateien im strengen JSON-Format","Muss formale Gerichtssprache verwenden und aggressive Anschuldigungen vermeiden"],"pt":["Exige adesão a regras rígidas e padrões de oração","Limitado a gerar arquivos PRAYER_PACK.json em formato JSON estrito","Deve usar linguagem formal de tribunal e evitar acusações agressivas"],"ru":["Требует соблюдения жестких правил и стандартов молитвы","Ограничен генерацией файлов PRAYER_PACK.json в формате JSON","Должен использовать формальный язык суда и избегать агрессивных обвинений"],"ar":["يتطلب اتباع قواعد صارمة ومعايير صلاة","محدود بتوليد ملفات PRAYER_PACK.json بتنسيق JSON صارم","يجب استخدام لغة رسمية للمحكمة وتجنب الاتهامات العدوانية"]},"version":3},"contentHash":"066e217b6c9fcb73b9ca6d26fa22701d7960c893c112d036b1b73345f84e5812","qualityScore":33}');
