INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('itmeGirish/BoardingMcp-Server/prayer-agent', 'prayer-agent', 'itmeGirish', 'BoardingMcp-Server', 'community', 'prayer-agent itmeGirish BoardingMcp-Server community Prayer Agent是一个MCP服务器，为Whatsp API提供AI智能代理功能 Prayer Agentは、MCPサーバーを使用してWhatsp APIのAIエージェント機能を提供するツールです Prayer Agent는 MCP 서버를 사용하여 Whatsp API의 AI 에이전트 기능을 제공하는 솔루션입니다 El agente de oración es un servidor MCP para la API de WhatsApp, diseñado para facilitar la integración L''agent de prière est un serveur MCP pour l''API WhatsApp, conçu pour faciliter l''intégration Der Gebetsagent ist ein MCP-Server für die WhatsApp-API, entwickelt zur Vereinfachung der Integration O Agente de Oração é um servidor MCP para a API do WhatsApp, permitindo a integração de funcionalidades de oração em suas aplicações ИИ Агент для Молитвы - это сервер MCP для WhatsApp API, позволяющий интегрировать функции молитвы в ваши приложения وكيل الصلاة هو خادم MCP ل API واتساب، يسمح بدمج وظائف الصلاة في تطبيقاتك It is mcp server for the whatsp api AI智能代理 MCP服务器 Whatsp API AI工具 如何使用Prayer Agent Prayer Agent安装 Prayer Agent替代品 It is mcp server for the whatsp api');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atiilla/Claude-Pentest-Agent-Ecosystem/ioc', 'community', 'atiilla', 'Claude-Pentest-Agent-Ecosystem', 'atiilla/Claude-Pentest-Agent-Ecosystem', 'ioc', 0, 0, 33, '2026-03-01T21:51:31Z', '2026-03-03T04:09:51.601Z', '02d20b10b3123921f8db6225cd44845bc28a2f94eeca012fe7af2d9bf587e2eb', '{"id":"atiilla/Claude-Pentest-Agent-Ecosystem/ioc","name":"ioc","description":{"zh":"ioc AIエージェント是一种综合的安全解决方案，适用于红队、蓝队和安全开发运营","ja":"ioc AIエージェントは、レッドチーム、ブルーチーム、セキュリティ開発運用のための総合的なセキュリティエージェントのコレクション","ko":"ioc AI 에이전트는 레드 팀, 블루 팀, 보안 개발 운용을 위한 종합적인 보안 에이전트의 모음","es":"La colección ioc ofrece agentes de seguridad especializados para equipos rojos, azules y operaciones de desarrollo de seguridad","fr":"La collection ioc propose des agents de sécurité spécialisés pour les équipes rouges, bleues et les opérations de développement de sécurité","de":"Die ioc-Sammlung bietet spezialisierte Sicherheitsagenten für Red- und Blue-Teams sowie Security-Development-Operations","pt":"A coleção ioc é um conjunto de agentes de segurança especializados para red teaming, blue teaming e desenvolvimento de operações de segurança","ru":"Коллекция ioc - это набор специализированных агентов безопасности для красной и синей команд, а также для разработки операций безопасности","ar":"مجموعة ioc هي مجموعة من الوكلاء الأمنيين المتخصصين للفريق الأحمر والفريق الأزرق وتطوير عمليات الأمن","en":"A comprehensive collection of specialized security agents for red teaming, blue teaming, and security development operations."},"seo":{"title":{"zh":"ioc AIエージェント：红队、蓝队和安全开发运营","ja":"ioc AIエージェント：レッドチーム、ブルーチーム、セキュリティ開発運用","ko":"ioc AI 에이전트: 레드 팀, 블루 팀, 보안 개발 운용","es":"Herramientas de seguridad ioc para equipos rojos y azules","fr":"Outils de sécurité ioc pour équipes rouges et bleues","de":"Sicherheits-Tools ioc für Red- und Blue-Teams","pt":"Ferramentas de Segurança ioc para Red Team e Blue Team","ru":"ИИ Агенты ioc для Красной и Синей Команд","ar":"أدوات الأمن الإلكتروني ioc للفريق الأحمر والفريق الأزرق","en":"ioc"},"description":{"zh":"ioc AIエージェント是一种综合的安全解决方案，适用于红队、蓝队和安全开发运营","ja":"ioc AIエージェントは、レッドチーム、ブルーチーム、セキュリティ開発運用のための総合的なセキュリティエージェントのコレクション","ko":"ioc AI 에이전트는 레드 팀, 블루 팀, 보안 개발 운용을 위한 종합적인 보안 에이전트의 모음","es":"La colección ioc ofrece agentes de seguridad especializados para equipos rojos, azules y operaciones de desarrollo de seguridad","fr":"La collection ioc propose des agents de sécurité spécialisés pour les équipes rouges, bleues et les opérations de développement de sécurité","de":"Die ioc-Sammlung bietet spezialisierte Sicherheitsagenten für Red- und Blue-Teams sowie Security-Development-Operations","pt":"A coleção ioc é um conjunto de agentes de segurança especializados para red teaming, blue teaming e desenvolvimento de operações de segurança","ru":"Коллекция ioc - это набор специализированных агентов безопасности для красной и синей команд, а также для разработки операций безопасности","ar":"مجموعة ioc هي مجموعة من الوكلاء الأمنيين المتخصصين للفريق الأحمر والفريق الأزرق وتطوير عمليات الأمن","en":"A comprehensive collection of specialized security agents for red teaming, blue teaming, and security development operations."},"definition":{"en":"A comprehensive collection of specialized security agents for red teaming, blue teaming, and security development operations."},"features":{"zh":["红队和蓝队安全测试","安全开发运营","自动化安全工具","综合的安全解决方案","支持多种安全协议"],"ja":["レッドチームとブルーチームのセキュリティテスト","セキュリティ開発運用","自動化セキュリティツール","総合的なセキュリティ解決策","多種のセキュリティプロトコルをサポート"],"ko":["레드 팀과 블루 팀의 보안 테스트","보안 개발 운용","자동화 보안 도구","종합적인 보안 솔루션","여러 보안 프로토콜 지원"],"es":["Agentes de seguridad especializados","Soporte para equipos rojos y azules","Integración con operaciones de desarrollo de seguridad","Herramientas de seguridad avanzadas","Compatibilidad con múltiples plataformas"],"fr":["Agents de sécurité spécialisés","Prise en charge des équipes rouges et bleues","Intégration avec les opérations de développement de sécurité","Outils de sécurité avancés","Compatibilité avec plusieurs plateformes"],"de":["Spezialisierte Sicherheitsagenten","Unterstützung für Red- und Blue-Teams","Integration mit Security-Development-Operations","Erweiterte Sicherheits-Tools","Kompatibilität mit mehreren Plattformen"],"pt":["Red teaming e blue teaming","Desenvolvimento de operações de segurança","Agentes de segurança especializados","Simulação de ataques e defesa","Análise de vulnerabilidades"],"ru":["Красная и синяя команда","Разработка операций безопасности","Специализированные агенты безопасности","Моделирование атак и защиты","Анализ уязвимостей"],"ar":["فريق الأحمر والفريق الأزرق","تطوير عمليات الأمن","وكلاء أمنيين متخصصين","تحسين الهجمات والدفاع","تحليل الثغرات"]},"keywords":{"zh":["ioc AIエージェント","红队安全测试","蓝队安全测试","安全开发运营","自动化安全工具","ioc 安装","ioc 教程","红队 vs 蓝队","安全开发运营工具"],"ja":["ioc AIエージェント","レッドチームセキュリティテスト","ブルーチームセキュリティテスト","セキュリティ開発運用","自動化セキュリティツール","ioc インストール","ioc チュートリアル","レッドチーム vs ブルーチーム","セキュリティ開発運用ツール"],"ko":["ioc AI 에이전트","레드 팀 보안 테스트","블루 팀 보안 테스트","보안 개발 운용","자동화 보안 도구","ioc 설치","ioc 튜토리얼","레드 팀 vs 블루 팀","보안 개발 운용 도구"],"es":["herramientas de seguridad ioc","cómo usar ioc","qué es ioc","ioc vs otros agentes de seguridad","alternativas a ioc","instalación de ioc","guía de configuración de ioc"],"fr":["outils de sécurité ioc","comment utiliser ioc","qu''est-ce que ioc","ioc vs autres agents de sécurité","alternatives à ioc","installation d''ioc","guide de configuration d''ioc"],"de":["Sicherheits-Tools ioc","wie man ioc verwendet","was ist ioc","ioc vs andere Sicherheitsagenten","Alternativen zu ioc","Installation von ioc","Konfigurationsanleitung für ioc"],"pt":["como usar ioc","o que é ioc","ioc vs ferramentas de segurança","instalar ioc","guias de configuração ioc","ferramentas de segurança para desenvolvedores","segurança cibernética","desenvolvimento de operações de segurança"],"ru":["как использовать ioc","что такое ioc","ioc vs инструменты безопасности","установить ioc","руководства по настройке ioc","инструменты безопасности для разработчиков","кибербезопасность","разработка операций безопасности"],"ar":["كيفية استخدام ioc","ما هي ioc","ioc مقابل أدوات الأمن","تثبيت ioc","دليل إعداد ioc","أدوات الأمن للمطورين","أمن المعلومات","تطوير عمليات الأمن"]}},"owner":"atiilla","repo":"Claude-Pentest-Agent-Ecosystem","repoPath":"atiilla/Claude-Pentest-Agent-Ecosystem","stars":0,"forks":0,"updatedAt":"2026-03-01T21:51:31Z","topics":[],"category":"community","skillMd":{"name":"ioc","description":"IOC extraction, enrichment, and threat intelligence correlation","bodyPreview":"# IOC Intelligence\n\nExtract and enrich indicators:\n- Extract IOCs from any source (reports, logs, samples)\n- Normalize and validate indicators\n- Enrich with threat intel (VT, AbuseIPDB, WHOIS)\n- Correlate infrastructure\n- Export in multiple formats\n\n## IOC Types\nIPv4/IPv6, domains, URLs, hashes (MD5/SHA1/SHA256), emails, registry keys, file paths, mutexes\n\n## Required Context\n1. **Source**: File path, text, or paste content\n2. **IOC Types**: All or specific types\n3. **Enrichment**: Basic (WHOIS)","body":"# IOC Intelligence\n\nExtract and enrich indicators:\n- Extract IOCs from any source (reports, logs, samples)\n- Normalize and validate indicators\n- Enrich with threat intel (VT, AbuseIPDB, WHOIS)\n- Correlate infrastructure\n- Export in multiple formats\n\n## IOC Types\nIPv4/IPv6, domains, URLs, hashes (MD5/SHA1/SHA256), emails, registry keys, file paths, mutexes\n\n## Required Context\n1. **Source**: File path, text, or paste content\n2. **IOC Types**: All or specific types\n3. **Enrichment**: Basic (WHOIS) or full (VT, Shodan)\n4. **Output**: JSON, CSV, STIX, MISP\n\n## Example\n```\n/ioc\nSource: threat_report.pdf\nEnrichment: Full\nOutput: JSON\n```\n"},"lastSynced":"2026-03-03T04:09:51.601Z","agentAnalysis":{"suitability":{"en":"Ideal for Threat Intelligence Agents requiring advanced Indicator of Compromise (IOC) analysis and enrichment capabilities.","zh":"适用于需要高级指标分析和丰富功能的威胁情报代理","ja":"Threat Intelligence Agent が高度な Indicator of Compromise (IOC) 分析および強化機能を必要とする場合に適しています","ko":"고급 지표 분석 및 보강 기능을 필요로하는 위협 지능 에이전트에 적합합니다","es":"Ideal para Agentes de Inteligencia de Amenazas que requieren un análisis y capacidades de enriquecimiento avanzadas de Indicadores de Compromiso (IOC).","fr":"Idéal pour les Agents d''Intelligence de Menace nécessitant une analyse et des capacités d''enrichissement avancées d''Indicateurs de Compromission (IOC).","de":"Ideal für Bedrohungs-Intelligenz-Agenten, die erweiterte Analyse- und Anreicherungsfunktionen für Indikatoren von Kompromissen (IOC) benötigen.","pt":"Ideal para Agentes de Inteligência de Ameaças que requerem análise e capacidades de enriquecimento avançadas de Indicador de Comprometimento (IOC).","ru":"Идеально для агентов угрозовой разведки, требующих расширенного анализа и возможностей обогащения Индикаторов компрометации (IOC).","ar":"مثالي للوكلاء استخبارات التهديد التي تتطلب تحليل متقدم وقدرات تعزيز للindicator من Compromise (IOC)."},"recommendation":{"en":"Empowers agents to extract and enrich IOCs from various sources, including reports and logs, utilizing threat intel from VT, AbuseIPDB, and WHOIS, and correlating infrastructure for comprehensive security insights.","zh":"赋予代理从各种源（包括报告和日志）提取和丰富 IOC 的能力，利用来自 VT、AbuseIPDB 和 WHOIS 的威胁情报，并将基础设施相关联以获取全面安全洞察","ja":"エージェントが VT、AbuseIPDB、WHOIS からの脅威インテリジェンスを利用して、レポートやログなどの様々なソースから IOC を抽出および強化し、インフラストラクチャを関連付けて包括的なセキュリティ洞察を得ることができるようにします","ko":"에이전트가 다양한 소스(예: 보고서 및 로그)에서 IOC를 추출하고 VT, AbuseIPDB 및 WHOIS의 위협 지능을 사용하여 보강하고, 인프라를 관련시키어 종합적인 보안 통찰력을 얻을 수 있도록 합니다","es":"Habilita a los agentes a extraer y enriquecer IOCs de diversas fuentes, incluyendo informes y registros, utilizando inteligencia de amenazas de VT, AbuseIPDB y WHOIS, y correlacionando infraestructuras para obtener información de seguridad integral.","fr":"Permet aux agents d''extraire et d''enrichir les IOC de diverses sources, y compris des rapports et des journaux, en utilisant l''intelligence de menace de VT, AbuseIPDB et WHOIS, et en corrélant les infrastructures pour obtenir des informations de sécurité globales.","de":"Ermöglicht es den Agenten, IOCs aus verschiedenen Quellen, einschließlich Berichten und Protokollen, zu extrahieren und zu bereichern, indem sie Bedrohungsinformationen von VT, AbuseIPDB und WHOIS nutzen und Infrastrukturen korrelieren, um umfassende Sicherheitserkenntnisse zu erhalten.","pt":"Habilita os agentes a extrair e enriquecer IOCs de várias fontes, incluindo relatórios e logs, utilizando inteligência de ameaças do VT, AbuseIPDB e WHOIS, e correlacionando infraestrutura para insights de segurança abrangentes.","ru":"Наделяет агентов возможностью извлекать и обогащать IOC из различных источников, включая отчеты и журналы, используя угрозную разведку от VT, AbuseIPDB и WHOIS, и коррелируя инфраструктуру для всесторонних сведений о безопасности.","ar":"تمكين الوكلاء لاستخراج وتعزيز IOCs من مصادر مختلفة، بما في ذلك التقارير وسجلات، باستخدام استخبارات التهديد من VT، AbuseIPDB وWHOIS، وترابط البنية التحتية للحصول على رؤى أمنية شاملة."},"useCases":{"en":["Extracting and normalizing IOCs from threat reports","Enriching indicators with threat intelligence from multiple sources","Correlating infrastructure for advanced security threat analysis"],"zh":["从威胁报告中提取和规范化 IOC","使用多个源的威胁情报来丰富指标","相关基础设施以进行高级安全威胁分析"],"ja":["脅威レポートから IOC を抽出および正規化する","複数のソースからの脅威インテリジェンスを使用して指標を強化する","インフラストラクチャを関連付けて高度なセキュリティ脅威分析を実施する"],"ko":["위협 보고서에서 IOC 추출 및 정규화","다중 소스의 위협 지능을 사용하여 지표 보강","인프라 관련을 통한 고급 보안 위협 분석"],"es":["Extraer y normalizar IOCs de informes de amenazas","Enriquecer indicadores con inteligencia de amenazas de múltiples fuentes","Correlacionar infraestructuras para un análisis de amenazas de seguridad avanzado"],"fr":["Extraire et normaliser les IOC de rapports de menaces","Enrichir les indicateurs avec l''intelligence de menace de multiples sources","Corréler les infrastructures pour une analyse de menace de sécurité avancée"],"de":["Extrahieren und Normalisieren von IOCs aus Bedrohungsberichten","Anreichern von Indikatoren mit Bedrohungsinformationen aus mehreren Quellen","Korrelieren von Infrastrukturen für eine erweiterte Sicherheitsbedrohungsanalyse"],"pt":["Extração e normalização de IOCs de relatórios de ameaças"," Enriquecimento de indicadores com inteligência de ameaças de múltiplas fontes"," Correlação de infraestrutura para análise de ameaças de segurança avançada"],"ru":["Извлечение и нормализация IOC из отчетов об угрозах","Обогащение индикаторов угрозной разведкой из нескольких источников","Корреляция инфраструктуры для расширенного анализа угроз безопасности"],"ar":["استخراج وت Normalize IOCs من تقارير التهديد","تحسين المؤشرات باستخدام استخبارات التهديد من مصادر متعددة","ترابط البنية التحتية لتحليل التهديدات الأمنية المتقدمة"]},"limitations":{"en":["Requires source input (file path, text, or paste content)","Limited to specific IOC types (IPv4/IPv6, domains, URLs, hashes, emails, registry keys, file paths, mutexes)"],"zh":["需要源输入（文件路径、文本或粘贴内容）","仅限于特定类型的 IOC（IPv4/IPv6、域名、URL、哈希、电子邮件、注册表键、文件路径、互斥体）"],"ja":["ソース入力（ファイルパス、テキスト、または貼り付けコンテンツ）が必要","特定の IOC 種類（IPv4/IPv6、ドメイン、URL、ハッシュ、メール、レジストリキー、ファイルパス、ミューテックス）のみに限定"],"ko":["소스 입력(파일 경로, 텍스트 또는 붙여넣기 콘텐츠)가 필요","특정 IOC 유형(IPv4/IPv6, 도메인, URL, 해시, 이메일, 레지스트리 키, 파일 경로, 뮤텍스)만 해당"],"es":["Requiere entrada de fuente (ruta de archivo, texto o contenido de pegado)","Limitado a tipos de IOC específicos (IPv4/IPv6, dominios, URLs, hashes, correos electrónicos, claves de registro, rutas de archivo, mutexes)"],"fr":["Nécessite une entrée de source (chemin de fichier, texte ou contenu collé)","Limité à des types d''IOC spécifiques (IPv4/IPv6, domaines, URL, hashes, adresses e-mail, clés de registre, chemins de fichiers, mutex)"],"de":["Benötigt Quelleneingabe (Dateipfad, Text oder Inhalt zum Einfügen)","Begrenzt auf bestimmte IOC-Typen (IPv4/IPv6, Domänen, URLs, Hashes, E-Mails, Registrierungsschlüssel, Dateipfade, Mutex)"],"pt":["Requer entrada de fonte (caminho do arquivo, texto ou conteúdo colado)","Limitado a tipos de IOC específicos (IPv4/IPv6, domínios, URLs, hashes, emails, chaves de registro, caminhos de arquivo, mutexes)"],"ru":["Требует ввода источника (путь к файлу, текст или содержимое буфера обмена)","Ограничен конкретными типами IOC (IPv4/IPv6, домены, URL, хеши, электронная почта, ключи реестра, пути к файлам, мьютексы)"],"ar":["يتطلب إدخال مصدر (مسار الملف، نص أو المحتوى المنسوخ)","محدود بنوع معين من IOC (IPv4/IPv6، نطاقات، URLs، كشاف، البريد الإلكتروني، مفاتيح السجل، مسارات الملفات، mutexes)"]},"version":3},"contentHash":"02d20b10b3123921f8db6225cd44845bc28a2f94eeca012fe7af2d9bf587e2eb","qualityScore":33}');
