INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('funfix/database/cats-effect-io', 'cats-effect-io', 'funfix', 'database', 'community', 'cats-effect-io funfix database community cats-effect-io是一个JVM数据库工具包，提供了简化数据库开发的功能 cats-effect-ioはJVM用のデータベースツールキットで、データベース開発を簡素化する機能を提供します cats-effect-io는 JVM용 데이터베이스 툴킷으로 데이터베이스 개발을 간소화하는 기능을 제공합니다 cats-effect-io es una herramienta de base de datos para JVM que facilita el desarrollo de aplicaciones cats-effect-io est un outil de base de données pour JVM qui facilite le développement d''applications cats-effect-io ist ein Datenbank-Toolkit für JVM, das die Entwicklung von Anwendungen erleichtert O cats-effect-io é uma ferramenta de banco de dados para a JVM, projetada para melhorar a eficiência dos projetos cats-effect-io - это инструмент для работы с базами данных на платформе JVM, предназначенный для повышения эффективности проектов cats-effect-io هي أداة قاعدة بيانات للأجهزة الافتراضية الجافا، مصممة لتحسين كفاءة المشاريع Database toolkit for the JVM cats-effect-io JVM数据库工具包 如何使用cats-effect-io cats-effect-io安装 cats-effect-io替代品 cats-effect-io教程 JVM数据库开发 数据库工具包 cats-effect-io setup guide Database toolkit for the JVM');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('iheanyi/tasuku/tasuku', 'community', 'iheanyi', 'tasuku', 'iheanyi/tasuku', 'tasuku', 0, 0, 33, '2026-03-04T13:07:01.809Z', '2026-03-04T14:32:55.452Z', '9cc7df6a181c5034480529cb86c332c6d11cf349b1feac7cb9df18a0b8852d49', '{"id":"iheanyi/tasuku/tasuku","name":"tasuku","description":{"zh":"Tasuku是一种轻量级多代理任务管理工具，促进代理知识捕获，适用于开发者","ja":"Tasukuは軽量級マルチエージェントタスク管理ツールであり、エージェント知識の捕獲を促進する","ko":"Tasuku는 경량级 다중 에이전트 작업 관리 도구로 에이전트 지식 캡처를 촉진하여 개발자에게 적합합니다","es":"tasuku es una herramienta ligera de gestión de tareas multiagente que promueve la captura de conocimiento de agentes","fr":"tasuku est un outil léger de gestion de tâches multi-agent qui favorise la capture des connaissances d''agent","de":"tasuku ist ein leichtgewichtiges Multi-Agenten-Aufgabenverwaltungstool, das die Erfassung von Agentenwissen fördert","pt":"Tasuku é uma ferramenta leve para gerenciamento de tarefas multi-agente que promove a captura de conhecimento agente.","ru":"Tasuku - это легкий инструмент для управления тасками multi-agent, который способствует захвату агентного знания.","ar":"Tasuku هو أداة خفيفة لإدارة المهام متعددة الوكيل التي تعزز إدارة المعرفة الوكيل.","en":"Lightweight multi-agent task management that promotes agentic knowledge capture "},"seo":{"title":{"zh":"Tasuku AI智能代理 - 轻量级多代理任务管理","ja":"Tasuku AIエージェント - 軽量級マルチエージェントタスク管理","ko":"Tasuku AI 에이전트 - 경량级 다중 에이전트 작업 관리","es":"Herramientas de AI: tasuku, gestión de tareas multiagente","fr":"Outils d''IA : tasuku, gestion de tâches multi-agent","de":"KI-Tools: tasuku, leichtgewichtige Multi-Agenten-Aufgaben...","pt":"Tasuku: Ferramenta de Gerenciamento de Tarefas de AI","ru":"Tasuku: Инструмент для управления тасками AI","ar":"Tasuku: أداة إدارة المهام من AI","en":"tasuku"},"description":{"zh":"Tasuku是一种轻量级多代理任务管理工具，促进代理知识捕获，适用于开发者","ja":"Tasukuは軽量級マルチエージェントタスク管理ツールであり、エージェント知識の捕獲を促進する","ko":"Tasuku는 경량级 다중 에이전트 작업 관리 도구로 에이전트 지식 캡처를 촉진하여 개발자에게 적합합니다","es":"tasuku es una herramienta ligera de gestión de tareas multiagente que promueve la captura de conocimiento de agentes","fr":"tasuku est un outil léger de gestion de tâches multi-agent qui favorise la capture des connaissances d''agent","de":"tasuku ist ein leichtgewichtiges Multi-Agenten-Aufgabenverwaltungstool, das die Erfassung von Agentenwissen fördert","pt":"Tasuku é uma ferramenta leve para gerenciamento de tarefas multi-agente que promove a captura de conhecimento agente.","ru":"Tasuku - это легкий инструмент для управления тасками multi-agent, который способствует захвату агентного знания.","ar":"Tasuku هو أداة خفيفة لإدارة المهام متعددة الوكيل التي تعزز إدارة المعرفة الوكيل.","en":"Lightweight multi-agent task management that promotes agentic knowledge capture "},"definition":{"en":"Lightweight multi-agent task management that promotes agentic knowledge capture "},"features":{"zh":["轻量级多代理任务管理","代理知识捕获","开发效率提高","支持多种开发语言","CLI接口"],"ja":["軽量級マルチエージェントタスク管理","エージェント知識の捕獲","開発効率の向上","多種の開発言語をサポート","CLIインターフェース"],"ko":["경량级 다중 에이전트 작업 관리","에이전트 지식 캡처","개발 효율성 향상","다양한 개발 언어 지원","CLI 인터페이스"],"es":["Gestión de tareas multiagente","Captura de conocimiento de agentes","Integración con herramientas de desarrollo","Interfaz de línea de comandos (CLI)","Compatibilidad con Python y Node.js"],"fr":["Gestion de tâches multi-agent","Capture des connaissances d''agent","Intégration avec les outils de développement","Interface de ligne de commande (CLI)","Compatibilité avec Python et Node.js"],"de":["Multi-Agenten-Aufgabenverwaltung","Erfassung von Agentenwissen","Integration mit Entwicklungstools","Kommandozeilen-Schnittstelle (CLI)","Kompatibilität mit Python und Node.js"],"pt":["Gerenciamento de tarefas multi-agente","Captura de conhecimento agente","Ferramenta leve para gerenciamento de tarefas"],"ru":["Управление тасками multi-agent","Захват агентного знания","Легкий инструмент для управления тасками"],"ar":["إدارة المهام متعددة الوكيل","إدارة المعرفة الوكيل","أداة خفيفة لإدارة المهام"]},"keywords":{"zh":["Tasuku AI智能代理","轻量级多代理任务管理","代理知识捕获","开发效率提高","Tasuku安装","Tasuku设置指南","Tasuku替代品","Tasuku vs 其他AI工具"],"ja":["Tasuku AIエージェント","軽量級マルチエージェントタスク管理","エージェント知識の捕獲","開発効率の向上","Tasukuのインストール","Tasukuの設定ガイド","Tasukuの代替品","Tasuku vs 他のAIツール"],"ko":["Tasuku AI 에이전트","경량级 다중 에이전트 작업 관리","에이전트 지식 캡처","개발 효율성 향상","Tasuku 설치","Tasuku 설정 가이드","Tasuku 대체品","Tasuku vs 다른 AI 도구"],"es":["herramientas de AI","gestión de tareas multiagente","captura de conocimiento de agentes","cómo usar tasuku","alternativas a tasuku","tasuku vs otros herramientas de AI","instalación de tasuku","guía de configuración de tasuku"],"fr":["outils d''IA","gestion de tâches multi-agent","capture des connaissances d''agent","comment utiliser tasuku","alternatives à tasuku","tasuku vs autres outils d''IA","installation de tasuku","guide de configuration de tasuku"],"de":["KI-Tools","Multi-Agenten-Aufgabenverwaltung","Erfassung von Agentenwissen","wie man tasuku verwendet","Alternativen zu tasuku","tasuku im Vergleich zu anderen KI-Tools","Installation von tasuku","Konfigurationsanleitung für tasuku"],"pt":["Tasuku","Ferramenta de gerenciamento de tarefas","AI","Agentes de AI","Gerenciamento de tarefas multi-agente"],"ru":["Tasuku","Инструмент для управления тасками","ИИ","Агенты ИИ","Управление тасками multi-agent"],"ar":["Tasuku","أداة لإدارة المهام","AI","أدوات AI","إدارة المهام متعددة الوكيل"]}},"owner":"iheanyi","repo":"tasuku","repoPath":"iheanyi/tasuku","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.809Z","topics":[],"category":"community","skillMd":{"name":"tasuku","description":"Agent-first task management. Use when tracking multi-session work, recording learnings/decisions, managing task dependencies, or persisting context across sessions. Provides tk_list, tk_add, tk_done, tk_start, tk_learn, tk_decide, tk_note, tk_show, tk_find, tk_ready, tk_context, tk_stats, tk_block, tk_task, tk_metadata, tk_manage, tk_health, tk_suggest, tk_deps, and tk_help tools.","bodyPreview":"# Tasuku — Agent-First Task Management\n\nTasuku provides persistent, git-friendly task management designed for AI agents working on codebases.\n\n## When to Use Tasuku\n\n- **Multi-session work**: Tasks, learnings, and decisions persist across sessions\n- **Task dependencies**: Block/unblock tasks, track what''s ready to work on\n- **Knowledge capture**: Record learnings (\"Never X\", \"Always Y\") and architectural decisions\n- **Project context**: Get a summary of project state at any time\n\n## Quick Start","body":"# Tasuku — Agent-First Task Management\n\nTasuku provides persistent, git-friendly task management designed for AI agents working on codebases.\n\n## When to Use Tasuku\n\n- **Multi-session work**: Tasks, learnings, and decisions persist across sessions\n- **Task dependencies**: Block/unblock tasks, track what''s ready to work on\n- **Knowledge capture**: Record learnings (\"Never X\", \"Always Y\") and architectural decisions\n- **Project context**: Get a summary of project state at any time\n\n## Quick Start\n\n### Check project state\nUse `tk_context` to get a full overview of tasks, learnings, and decisions.\n\n### Pick up work\nUse `tk_ready` to see tasks ready to work on, then `tk_start` to begin.\n\n### Track progress\n- `tk_add` — Create new tasks\n- `tk_note` — Add progress notes to tasks\n- `tk_done` — Mark tasks complete\n\n### Capture knowledge\n- `tk_learn` — Record insights, gotchas, rules (\"Never manually edit ANSI strings\")\n- `tk_decide` — Record architectural decisions with alternatives and reasoning\n\n## Task vs Session Scope\n\nUse Tasuku for **project-level** work that spans sessions:\n- Features, bugs, milestones\n- Architectural decisions\n- Cross-cutting learnings\n\nUse your editor''s built-in task list for **session-level** steps:\n- Implementation steps within a single session\n- Temporary checklists\n\n## Workflow Commands\n\n### Starting a Session\n1. `tk_context` — See project overview\n2. `tk_ready` — Find next task to work on\n3. `tk_start` — Begin working on a task\n\n### During Work\n- `tk_note` — Record progress, blockers, or findings\n- `tk_learn` — Capture insights as you discover them\n- `tk_block` — Mark tasks blocked by other tasks\n\n### Completing Work\n1. `tk_done` — Mark task complete\n2. `tk_learn` — Capture what you learned (don''t skip this!)\n3. `tk_ready` — See what''s unblocked and ready next\n\n### Finding Information\n- `tk_find` — Search across tasks, learnings, and decisions\n- `tk_show` — Get full details on a specific task\n- `tk_deps` — See task dependency graph\n- `tk_stats` — Project health metrics\n"},"lastSynced":"2026-03-04T14:32:55.452Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring persistent and git-friendly task management for collaborative codebase development.","zh":"适用于需要持久和git友好任务管理的AI代理进行协作代码库开发。","ja":"AIエージェントが持続的なタスク管理とgitに優しいタスク管理を必要とするコラボレーションコードベース開発に最適。","ko":"지속적이고 git 친화적인 작업 관리가 필요한 AI 에이전트를 위한 협업 코드베이스 개발에 적합합니다.","es":"Ideal para agentes de IA que requieren una gestión de tareas persistente y compatible con git para el desarrollo de código colaborativo.","fr":"Idéal pour les agents IA nécessitant une gestion de tâches persistante et compatible avec git pour le développement de code collaboratif.","de":"Ideal für KI-Agents, die eine persistente und git-freundliche Aufgabenverwaltung für die Entwicklung von Collaborative-Codebases benötigen.","pt":"Ideal para agentes de IA que requerem gerenciamento de tarefas persistente e compatível com git para desenvolvimento de código colaborativo.","ru":"Идеально для агентов ИИ, требующих постоянного и совместимого с git управления задачами для разработки кодовой базы.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يتطلب إدارة المهام المستدامة ومتوافقة مع جيت للتنمية التعاونية لقاعدة الشفرة."},"recommendation":{"en":"Empowers agents to capture knowledge and architectural decisions using lightweight multi-agent task management, promoting task dependencies and persistent learnings across sessions with git-friendly compatibility.","zh":"赋予代理捕获知识和架构决策的能力，使用轻量级多代理任务管理，促进任务依赖和会话间的持久学习，并具有git友好兼容性。","ja":"エージェントに知識とアーキテクチャの決定をキャプチャする能力を与え、軽量のマルチエージェントタスク管理を使用して、タスクの依存関係とセッション間の永続的な学習を促進し、gitに優しい互換性を提供する。","ko":"에이전트가 지식과 아키텍처 결정을 캡처할 수 있는 능력을 부여하여 가벼운 멀티 에이전트 작업 관리를 사용하여 작업 의존성 및 세션 간의 지속적인 학습을 촉진하고 git 친화적인 호환성을 제공합니다.","es":"Permite a los agentes capturar conocimientos y decisiones arquitectónicas utilizando una gestión de tareas de múltiples agentes ligera, promoviendo las dependencias de tareas y los aprendizajes persistentes en sesiones con compatibilidad con git.","fr":"Permet aux agents de capturer les connaissances et les décisions architecturales en utilisant une gestion de tâches multi-agents légère, promouvant les dépendances de tâches et les apprentissages persistants lors des sessions avec une compatibilité git.","de":"Ermächtigt Agents, Wissen und architektonische Entscheidungen mit einer leichten Multi-Agent-Aufgabenverwaltung zu erfassen, fördert Aufgabenabhängigkeiten und persistente Lernprozesse über Sitzungen hinweg mit git-freundlicher Kompatibilität.","pt":"Habilita os agentes a capturar conhecimento e decisões arquitetônicas usando gerenciamento de tarefas leve de multi-agente, promovendo dependências de tarefas e aprendizados persistentes em várias sessões com compatibilidade com git.","ru":"Наделяет агентов возможностью захватить знания и архитектурные решения с помощью легкого управления задачами мультиагента, продвигая зависимости задач и постоянное обучение на протяжении сессий с совместимостью с git.","ar":"يمنح الوكلاء القدرة على التقاط المعرفة والقرارات المعمارية باستخدام إدارة المهام الخفيفة متعددة الوكلاء، وتعزيز зависимости المهام والتعلم المستدام عبر الجلسات مع توافق جيت."},"useCases":{"en":["Managing multi-session work with persistent task tracking","Automating task dependency analysis for efficient workflow","Capturing and recording agentic knowledge for project context summaries"],"zh":["管理具有持久任务跟踪的多会话工作","自动执行任务依赖分析以实现高效的工作流程","捕获和记录代理知识以用于项目上下文摘要"],"ja":["永続的なタスク追跡を使用したマルチセッション作業の管理","効率的なワークフローを実現するためのタスク依存解析の自動化","プロジェクトコンテキストサマリー用のエージェント知識のキャプチャと記録"],"ko":["지속적인 작업 추적을 사용한 멀티 세션 작업 관리","효율적인 워크플로우를实现하기 위한 작업 의존성 분석의 자동화","프로젝트 컨텍스트 요약을 위한 에이전트 지식의 캡처 및 기록"],"es":["Gestión de trabajo en varias sesiones con seguimiento de tareas persistente","Automatización del análisis de dependencias de tareas para un flujo de trabajo eficiente","Captura y grabación del conocimiento de los agentes para resúmenes de contexto de proyecto"],"fr":["Gestion de travail en plusieurs sessions avec suivi de tâches persistant","Automatisation de l''analyse des dépendances de tâches pour un flux de travail efficace","Capturation et enregistrement des connaissances des agents pour des résumés de contexte de projet"],"de":["Verwaltung von Mehrsitzungsarbeiten mit persistenter Aufgabenverfolgung","Automatisierung der Aufgabenabhängigkeitsanalyse für einen effizienten Arbeitsablauf","Erfassung und Aufzeichnung des Wissens von Agents für Projektzusammenfassungen"],"pt":["Gerenciamento de trabalho de várias sessões com rastreamento de tarefas persistente","Automatização da análise de dependência de tarefas para fluxo de trabalho eficiente","Captura e gravação do conhecimento agêntico para resumos de contexto de projeto"],"ru":["Управление работой в нескольких сессиях с постоянным отслеживанием задач","Автоматизация анализа зависимости задач для эффективного рабочего процесса","Захват и запись агентских знаний для сводок контекста проекта"],"ar":["إدارة عمل الجلسات المتعددة مع تتبع المهام المستدام","أتمتة تحليل зависимости المهام من أجل سير عمل فعال","التقاط وتسجيل المعرفة الوكيلية لأجل ملخصات سياق المشروع"]},"limitations":{"en":["Requires git compatibility for version control","Designed specifically for codebase development tasks"],"zh":["需要git兼容性以进行版本控制","专门为代码库开发任务设计"],"ja":["バージョン管理のためにgitの互換性が必要","コードベース開発タスク専用に設計"],"ko":["버전 관리를 위해 git 호환성이 필요","코드베이스 개발 작업専用로 설계"],"es":["Requiere compatibilidad con git para el control de versiones","Diseñado específicamente para tareas de desarrollo de código"],"fr":["Nécessite une compatibilité avec git pour le contrôle de version","Conçu spécifiquement pour les tâches de développement de code"],"de":["Erfordert git-Kompatibilität für die Versionskontrolle","Speziell für Code-Entwicklungsaufgaben konzipiert"],"pt":["Requer compatibilidade com git para controle de versão","Projetado especificamente para tarefas de desenvolvimento de código"],"ru":["Требует совместимости с git для контроля версий","Разработан специально для задач разработки кодовой базы"],"ar":["يتطلب توافقًا مع جيت للسيطرة على الإصدار","صمّم خصيصًا لمهام تطوير قاعدة الشفرة"]},"version":3},"contentHash":"9cc7df6a181c5034480529cb86c332c6d11cf349b1feac7cb9df18a0b8852d49","qualityScore":33}');
