INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arkanwolfshade/MythosMUD/mythosmud-logging-standards', 'mythosmud-logging-standards', 'arkanwolfshade', 'MythosMUD', 'community', 'mythosmud-logging-standards arkanwolfshade MythosMUD community MythosMUD 日志标准是一种基于克苏鲁神话的文本多用户地下城（MUD），提供了一个独特的浏览器可访问的游戏体验 MythosMUD ロギングスタンダードは、クトゥルー神話に影響されたテキストベースのマルチユーザードンジョン（MUD）であり、ブラウザーアクセス可能なユニークなゲーム体験を提供します MythosMUD 로깅 표준은 크툴루 신화에 기반한 텍스트 기반 다중 사용자 던전(MUD)으로, 브라우저에서 접근할 수 있는 고유한 게임 경험을 제공합니다 mythosmud-logging-standards es un entorno de dungeon multiusuario basado en texto, accesible desde el navegador mythosmud-logging-standards est un environnement de donjon multiutilisateur basé sur du texte, accessible depuis le navigateur mythosmud-logging-standards ist eine Multi-User-Dungeon-Umgebung basierend auf Text, über den Browser zugänglich O mythosmud-logging-standards é uma ferramenta de IA para criação de jogos de texto inspirados no Mito de Cthulhu ИИ Агент mythosmud-logging-standards - это инструмент для создания текстовых игр, вдохновлённых Мифом Ктулху أداة الذكاء الاصطناعي mythosmud-logging-standards هي أداة لإنشاء ألعاب نصية مستوحاة من ميثوس كثولو A text-based, browser-accessible Multi-User Dungeon (MUD) inspired by the Cthulhu Mythos. AI工具 MythosMUD 日志标准 文本多用户地下城 克苏鲁神话 如何使用MythosMUD MythosMUD安装 MythosMUD设置指南 A text-based, browser-accessible Multi-User Dungeon (MUD) inspired by the Cthulhu Mythos.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LucasSantana-Dev/LukBot/music-queue-player', 'community', 'LucasSantana-Dev', 'LukBot', 'LucasSantana-Dev/LukBot', 'music-queue-player', 0, 0, 33, '2026-03-04T13:07:01.819Z', '2026-03-04T14:37:52.611Z', '5574013d0cdd1352e72b74f12599cefc56c8cdc35b15351764adb367530309e6', '{"id":"LucasSantana-Dev/LukBot/music-queue-player","name":"music-queue-player","description":{"zh":"这是一个使用Typescript开发的Discord音乐队列机器人，具有音乐和管理工具","ja":"TypeScriptで開発されたDiscordミュージックキューBOT、音楽と管理ツールを備えています","ko":"타입스크립트로 개발된 디스코드 음악 큐 플레이어, 음악 및 관리 도구를 제공합니다","es":"Este bot de Discord desarrollado con Typescript ofrece herramientas de moderación y música para una experiencia enriquecedora.","fr":"Ce bot Discord développé avec Typescript propose des outils de modération et de musique pour une expérience enrichissante.","de":"Dieser Discord-Bot, entwickelt mit Typescript, bietet Moderations- und Musik-Tools für eine bereichernde Erfahrung.","pt":"O music-queue-player é um bot de Discord desenvolvido em Typescript com recursos de moderação e música","ru":"ИИ Агент music-queue-player - это бот Discord, созданный на Typescript с функциями модерации и музыки","ar":"أداة music-queue-player هي bot ديسكورد مبنية على Typescript مع أدوات المودeration والموسيقى","en":"This is a Discord bot i made with Typescript. It has moderation and music tools."},"seo":{"title":{"zh":"Discord音乐队列机器人 - AI智能工具","ja":"DiscordミュージックキューBOT - AIエージェント","ko":"디스코드 음악 큐 플레이어 - AI 에이전트","es":"Reproductor de cola de música para Discord con Herramient...","fr":"Lecteur de file d''attente musicale pour Discord avec Outi...","de":"Musik-Warteschleifen-Player für Discord mit KI-Tools","pt":"Ferramenta de Música e Moderação para Discord","ru":"ИИ Агент: Музыкальный Плеер и Модерация для Discord","ar":"أداة تشغيل الموسيقى وأدوات المодération لديسكورد","en":"music-queue-player"},"description":{"zh":"这是一个使用Typescript开发的Discord音乐队列机器人，具有音乐和管理工具","ja":"TypeScriptで開発されたDiscordミュージックキューBOT、音楽と管理ツールを備えています","ko":"타입스크립트로 개발된 디스코드 음악 큐 플레이어, 음악 및 관리 도구를 제공합니다","es":"Este bot de Discord desarrollado con Typescript ofrece herramientas de moderación y música para una experiencia enriquecedora.","fr":"Ce bot Discord développé avec Typescript propose des outils de modération et de musique pour une expérience enrichissante.","de":"Dieser Discord-Bot, entwickelt mit Typescript, bietet Moderations- und Musik-Tools für eine bereichernde Erfahrung.","pt":"O music-queue-player é um bot de Discord desenvolvido em Typescript com recursos de moderação e música","ru":"ИИ Агент music-queue-player - это бот Discord, созданный на Typescript с функциями модерации и музыки","ar":"أداة music-queue-player هي bot ديسكورد مبنية على Typescript مع أدوات المودeration والموسيقى","en":"This is a Discord bot i made with Typescript. It has moderation and music tools."},"definition":{"en":"This is a Discord bot i made with Typescript. It has moderation and music tools."},"features":{"zh":["音乐播放功能","管理工具","Discord集成","使用Typescript开发","易于设置和使用"],"ja":["音楽再生機能","管理ツール","Discordとの統合","TypeScriptで開発","簡単な設定と使用"],"ko":["음악 재생 기능","관리 도구","디스코드 통합","타입스크립트로 개발","쉽게 설정 및 사용"],"es":["Desarrollado con Typescript","Herramientas de moderación avanzadas","Reproducción de música en servidores de Discord","Integración con Discord para una experiencia sin problemas","Personalización de la cola de música según las preferencias del usuario"],"fr":["Développé avec Typescript","Outils de modération avancés","Lecture de musique sur les serveurs Discord","Intégration avec Discord pour une expérience sans problème","Personnalisation de la file d''attente musicale selon les préférences de l''utilisateur"],"de":["Entwickelt mit Typescript","Erweiterte Moderations-Tools","Wiedergabe von Musik auf Discord-Servern","Integration mit Discord für eine reibungslose Erfahrung","Anpassung der Musik-Warteschleife an die Benutzerpräferenzen"],"pt":["Desenvolvido em Typescript","Ferramentas de moderação avançadas","Reprodução de música de alta qualidade","Integração com o Discord","Código aberto e personalizável"],"ru":["Разработан на Typescript","Продвинутые инструменты модерации","Воспроизведение музыки высокого качества","Интеграция с Discord","Открытый и настраиваемый код"],"ar":["تم تطويره باستخدام Typescript","أدوات المودeration المتقدمة","تشغيل الموسيقى بجودة عالية","التكامل مع ديسكورد","الرمز المفتوح والقابل للتعديل"]},"keywords":{"zh":["如何使用Discord音乐队列机器人","什么是AI智能工具","Discord音乐队列机器人替代品","Discord音乐队列机器人安装","Discord音乐队列机器人设置指南","Discord音乐队列机器人与其他工具的比较"],"ja":["DiscordミュージックキューBOTの使い方","AIエージェントとは","DiscordミュージックキューBOTの代替","DiscordミュージックキューBOTのインストール","DiscordミュージックキューBOTの設定ガイド","DiscordミュージックキューBOTと他のツールの比較"],"ko":["디스코드 음악 큐 플레이어 사용 방법","AI 에이전트란","디스코드 음악 큐 플레이어 대체","디스코드 음악 큐 플레이어 설치","디스코드 음악 큐 플레이어 설정 가이드","디스코드 음악 큐 플레이어와 다른 도구의 비교"],"es":["cómo usar reproductor de cola de música para Discord","qué es un reproductor de cola de música para Discord","reproductor de cola de música para Discord alternativa","reproductor de cola de música para Discord vs otros bots","instalación de reproductor de cola de música para Discord","guía de configuración de reproductor de cola de música para Discord","herramientas de IA para Discord","desarrollo de bots de Discord con Typescript"],"fr":["comment utiliser le lecteur de file d''attente musicale pour Discord","qu''est-ce qu''un lecteur de file d''attente musicale pour Discord","lecteur de file d''attente musicale pour Discord alternative","lecteur de file d''attente musicale pour Discord vs autres bots","installation du lecteur de file d''attente musicale pour Discord","guide de configuration du lecteur de file d''attente musicale pour Discord","outils d''IA pour Discord","développement de bots Discord avec Typescript"],"de":["wie man den Musik-Warteschleifen-Player für Discord verwendet","was ist ein Musik-Warteschleifen-Player für Discord","Musik-Warteschleifen-Player für Discord Alternative","Musik-Warteschleifen-Player für Discord vs andere Bots","Installation des Musik-Warteschleifen-Players für Discord","Einrichtungsanleitung für den Musik-Warteschleifen-Player für Discord","KI-Tools für Discord","Entwicklung von Discord-Bots mit Typescript"],"pt":["como usar music-queue-player","o que é music-queue-player","alternativas para music-queue-player","music-queue-player vs outros bots","instalar music-queue-player","guia de configuração do music-queue-player"],"ru":["как использовать music-queue-player","что такое music-queue-player","альтернативы music-queue-player","music-queue-player vs другие боты","установить music-queue-player","руководство по настройке music-queue-player"],"ar":["كيفية استخدام أداة music-queue-player","ما هي أداة music-queue-player","بديلات أداة music-queue-player","أداة music-queue-player مقابل أدوات أخرى","تثبيت أداة music-queue-player","دليل إعداد أداة music-queue-player"]}},"owner":"LucasSantana-Dev","repo":"LukBot","repoPath":"LucasSantana-Dev/LukBot","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.819Z","topics":[],"category":"community","skillMd":{"name":"music-queue-player","description":"Work with Discord Player, queue, and music commands in LukBot. Use when changing play/queue/skip/volume, track handling, or player lifecycle.","bodyPreview":"# LukBot Music & Queue\n\n## When to use\n\n- Changing play, queue, skip, pause, volume, autoplay, repeat, shuffle\n- Fixing track or queue display\n- Player lifecycle, errors, or extractors\n\n## Player access\n\n- Use `useMainPlayer()` from `discord-player` where the player is available (e.g. after client ready).\n- Play: `player.play(voiceChannel, searchResult, { nodeOptions: { metadata } })`. Search via `player.search(query, { requestedBy })`.\n\n## Command locations\n\n- **Play**: `packages/bot/src/functi","body":"# LukBot Music & Queue\n\n## When to use\n\n- Changing play, queue, skip, pause, volume, autoplay, repeat, shuffle\n- Fixing track or queue display\n- Player lifecycle, errors, or extractors\n\n## Player access\n\n- Use `useMainPlayer()` from `discord-player` where the player is available (e.g. after client ready).\n- Play: `player.play(voiceChannel, searchResult, { nodeOptions: { metadata } })`. Search via `player.search(query, { requestedBy })`.\n\n## Command locations\n\n- **Play**: `packages/bot/src/functions/music/commands/play/` — processor, queryDetector, queueManager, spotify/youtube handlers\n- **Queue**: `packages/bot/src/functions/music/commands/queue/` — formatter, embed, grouping, stats\n- **Control**: `packages/bot/src/functions/music/commands/` — skip, pause, resume, remove, clear, volume, repeat, shuffle, leave, stop\n\n## Handlers\n\n- **Player**: `packages/bot/src/handlers/player/` — trackHandlers, errorHandlers, lifecycleHandlers, playerFactory\n- **Events**: `packages/bot/src/handlers/player/trackHandlers.ts` and related — wire player events to replies and history\n\n## Shared state\n\n- Track history and recommendations: use services from `@lukbot/shared` (e.g. TrackHistoryService, recommendation) when persisting; do not duplicate queue state in Redis/DB beyond what shared exposes.\n\n## Validations\n\n- Ensure user is in a voice channel; bot has join permissions. Use existing queue/voice validators before touching queue or player.\n"},"lastSynced":"2026-03-04T14:37:52.611Z","agentAnalysis":{"suitability":{"en":"Perfect for Discord Agents needing advanced music queue management capabilities.","zh":"非常适合需要高级音乐队列管理功能的Discord Agents。","ja":"高度な音楽キュー管理機能を必要とするDiscordエージェントに最適です。","ko":"고급 음악 큐 관리 기능이 필요한 Discord 에이전트에게 적합합니다.","es":"Perfecto para agentes de Discord que necesitan capacidades de gestión avanzada de cola de música.","fr":"Parfait pour les agents Discord ayant besoin de fonctionnalités de gestion de file d''attente de musique avancées.","de":"Perfekt für Discord-Agents, die erweiterte Musik-Warteschlangen-Management-Funktionen benötigen.","pt":"Perfeito para Agentes do Discord que necessitam de capacidades avançadas de gerenciamento de filas de música.","ru":"Идеально для агентов Discord, которым необходимы продвинутые возможности управления музыкальными очередями.","ar":"مثالي للوكلاء Discord الذين يحتاجون إلى إمكانيات متقدمة لإدارة طوابير الموسيقى."},"recommendation":{"en":"Empowers agents to control music playback using discord-player, enabling features like play, pause, skip, and volume adjustment via voice channel interactions and search queries with metadata.","zh":"通过discord-player赋予代理控制音乐播放的能力，实现通过语音频道交互和带有元数据的搜索查询启用诸如播放、暂停、跳过和音量调整等功能。","ja":"discord-playerを使用してエージェントが音楽の再生を制御できるようにし、音声チャンネルのやり取りやメタデータを含む検索クエリを使用して、再生、停止、スキップ、音量調整などの機能を有効にします。","ko":"discord-player를 통해 에이전트가 음악 재생을 제어할 수 있도록 하며, 음성 채널 상호 작용 및 메타데이터가 포함된 검색 쿼리를 통해 재생, 일시 중지, 건너뛰기 및 볼륨 조정 등의 기능을 사용할 수 있습니다.","es":"Habilita a los agentes a controlar la reproducción de música mediante discord-player, lo que permite funciones como reproducir, pausar, saltar y ajustar el volumen a través de interacciones de canales de voz y consultas de búsqueda con metadatos.","fr":"Permet aux agents de contrôler la lecture de musique à l''aide de discord-player, permettant des fonctionnalités comme lecture, pause, saut et ajustement du volume via des interactions de canaux vocaux et des requêtes de recherche avec des métadonnées.","de":"Ermöglicht es Agenten, die Musikwiedergabe mithilfe von discord-player zu steuern, wodurch Funktionen wie Wiedergabe, Pause, Überspringen und Lautstärkeanpassung über Sprachkanalinteraktionen und Suchabfragen mit Metadaten ermöglicht werden.","pt":"Habilita os agentes a controlar a reprodução de música usando discord-player, permitindo recursos como reproduzir, pausar, pular e ajustar o volume por meio de interações de canal de voz e consultas de pesquisa com metadados.","ru":"Наделяет агентов возможностью контролировать проигрывание музыки с помощью discord-player, обеспечивая функции, такие как проигрывание, пауза, пропуск и регулировка громкости через взаимодействия голосового канала и запросы поиска с метаданными.","ar":"يمكن الوكلاء من التحكم في تشغيل الموسيقى باستخدام discord-player، وتمكين الميزات مثل التشغيل و الإيقاف المؤقت و التنقل و ضبط الصوت من خلال تفاعلات قناة الصوت و استفسارات البحث مع البيانات الوصفية."},"useCases":{"en":["Automating music playlists with autoplay and repeat","Managing music queues with skip, pause, and volume controls","Debugging track or queue display issues"],"zh":["使用autoplay和repeat实现音乐播放列表的自动化","使用skip、pause和volume控件管理音乐队列","调试音轨或队列显示问题"],"ja":["autoplayとrepeatを使用して音楽プレイリストを自動化する","skip、pause、volumeコントロールを使用して音楽キューを管理する","トラックまたはキューの表示に関する問題をデバッグする"],"ko":["autoplay와 repeat를 사용하여 음악 플레이리스트를 자동화하는 것","skip, pause 및 볼륨 컨트롤을 사용하여 음악 큐를 관리하는 것","트랙 또는 큐 표시 문제를 디버깅하는 것"],"es":["Automatizar listas de reproducción de música con autoplay y repetición","Gestionar colas de música con controles de salto, pausa y volumen","Depurar problemas de visualización de pistas o colas"],"fr":["Automatiser les listes de lecture de musique avec autoplay et répétition","Gérer les files d''attente de musique avec des contrôles de saut, de pause et de volume","Déboguer les problèmes d''affichage de pistes ou de files d''attente"],"de":["Automatisieren von Musikwiedergabelisten mit Autoplay und Wiederholung","Verwalten von Musikwarteschlangen mit Überspringen-, Pause- und Lautstärkensteuerung","Fehler bei der Anzeige von Tracks oder Warteschlangen beheben"],"pt":["Automatizar listas de reprodução de música com reprodução automática e repetição","Gerenciar filas de música com controles de pular, pausar e volume","Depurar problemas de exibição de faixas ou filas"],"ru":["Автоматизировать музыкальные плейлисты с автозапуском и повтором","Управлять музыкальными очередями с помощью контроля пропуска, паузы и громкости","Отладка проблем отображения треков или очередей"],"ar":["توفير قوائم تشغيل موسيقية تلقائية مع التشغيل التلقائي و الإعادة","إدارة طوابير الموسيقى مع عناصر تحكم في التنقل و الإيقاف المؤقت و الصوت","تصحيح مشاكل في عرض المسارات أو الطوابير"]},"limitations":{"en":["Requires discord-player library","Typescript implementation","Discord bot setup necessary"],"zh":["需要discord-player库","Typescript实现","Discord机器人设置是必要的"],"ja":["discord-playerライブラリが必要","Typescriptの実装","Discordボットの設定が必要"],"ko":["discord-player 라이브러리가 필요함","Typescript 구현","Discord 봇 설정이 필요함"],"es":["Requiere la biblioteca discord-player","Implementación de Typescript","Configuración de bot de Discord necesaria"],"fr":["Nécessite la bibliothèque discord-player","Mise en œuvre de Typescript","Configuration du bot Discord nécessaire"],"de":["Benötigt die discord-player-Bibliothek","Typescript-Implementierung","Discord-Bot-Konfiguration erforderlich"],"pt":["Requer biblioteca discord-player","Implementação em Typescript","Configuração de bot do Discord necessária"],"ru":["Требуется библиотека discord-player","Реализация на Typescript","Необходима настройка бота Discord"],"ar":["يتطلب مكتبة discord-player","تنفيذ بلغة Typescript","ضرورة إعداد بوت Discord"]},"version":3},"contentHash":"5574013d0cdd1352e72b74f12599cefc56c8cdc35b15351764adb367530309e6","qualityScore":33}');
