INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LucasSantana-Dev/LukBot/music-queue-player', 'music-queue-player', 'LucasSantana-Dev', 'LukBot', 'community', 'music-queue-player LucasSantana-Dev LukBot community 这是一个使用Typescript开发的Discord音乐队列机器人，具有音乐和管理工具 TypeScriptで開発されたDiscordミュージックキューBOT、音楽と管理ツールを備えています 타입스크립트로 개발된 디스코드 음악 큐 플레이어, 음악 및 관리 도구를 제공합니다 Este bot de Discord desarrollado con Typescript ofrece herramientas de moderación y música para una experiencia enriquecedora. Ce bot Discord développé avec Typescript propose des outils de modération et de musique pour une expérience enrichissante. Dieser Discord-Bot, entwickelt mit Typescript, bietet Moderations- und Musik-Tools für eine bereichernde Erfahrung. O music-queue-player é um bot de Discord desenvolvido em Typescript com recursos de moderação e música ИИ Агент music-queue-player - это бот Discord, созданный на Typescript с функциями модерации и музыки أداة music-queue-player هي bot ديسكورد مبنية على Typescript مع أدوات المودeration والموسيقى This is a Discord bot i made with Typescript. It has moderation and music tools. 如何使用Discord音乐队列机器人 什么是AI智能工具 Discord音乐队列机器人替代品 Discord音乐队列机器人安装 Discord音乐队列机器人设置指南 Discord音乐队列机器人与其他工具的比较 This is a Discord bot i made with Typescript. It has moderation and music tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jorggerojas/next-skeleton-page/pages-router', 'community', 'jorggerojas', 'next-skeleton-page', 'jorggerojas/next-skeleton-page', 'pages-router', 0, 0, 33, '2026-03-04T13:07:01.825Z', '2026-03-04T14:41:09.526Z', 'ea5998cbd256ae4ab1cbff2df166d0c75a100ef3e2fad61d96ab8c6f0daf7da7', '{"id":"jorggerojas/next-skeleton-page/pages-router","name":"pages-router","description":{"zh":"Pages Router是一个Next.js页面路由器模板，帮助您快速构建页面","ja":"Pages RouterはNext.jsページルーターのテンプレートで、ページを迅速に構築するのに役立ちます","ko":"Pages Router는 Next.js 페이지 라우터 템플릿으로 페이지를 빠르게 구축하는 데 도움이 됩니다","es":"Pages-router es un repositorio de plantillas para Next.js que te permite trabajar más rápido con una arquitectura limpia y MCP","fr":"Pages-router est un dépôt de modèles pour Next.js qui vous permet de travailler plus rapidement avec une architecture propre et MCP","de":"Pages-router ist ein Repository-Vorlagen für Next.js, das es Ihnen ermöglicht, schneller mit einer sauberen Architektur und MCP zu arbeiten","pt":"O pages-router é um modelo de repositório para Next.js que permite começar a trabalhar mais rápido com uma arquitetura limpa e simples","ru":"Pages-router - это шаблон репозитория для Next.js, который позволяет начать работать быстрее с чистой и простой архитектурой","ar":"pages-router هو قالب مخزن لموقع Next.js يسمح بالبدء في العمل بشكل أسرع مع هندسة نظيفة وبسيطة","en":"Next.js Pages router repo template to start working faster in a very simple clean architecture and mcp skills."},"seo":{"title":{"zh":"AI智能工具 Pages Router","ja":"AIエージェント Pages Router","ko":"AI 에이전트 Pages Router","es":"Herramientas de AI: pages-router para Next.js","fr":"Outils IA: pages-router pour Next.js","de":"KI-Tools: pages-router für Next.js","pt":"Ferramentas de IA: pages-router para Next.js","ru":"ИИ Агенты: pages-router для Next.js","ar":"أدوات الذكاء الاصطناعي: pages-router ل