INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('technologi-service/arepaflow/og-image-generation', 'og-image-generation', 'technologi-service', 'arepaflow', 'community', 'og-image-generation technologi-service arepaflow community og-image-generation AI智能代理，用于生成og图片，基于Next.js 16、Neon Postgres和Drizzle ORM og画像生成のAIエージェント、Next.js 16、Neon Postgres、Drizzle ORMを使用 og 이미지 생성 AI 에이전트, Next.js 16, Neon Postgres, Drizzle ORM을 사용 ArepaFlow es un sistema de pedidos y entregas de arepas venezolanas construido con tecnologías avanzadas como Next.js 16, Neon Postgres y Drizzle ORM ArepaFlow est un système de commandes et de livraisons d''arepas vénézuéliennes créé avec des technologies avancées comme Next.js 16, Neon Postgres et Drizzle ORM ArepaFlow ist ein System für Bestellungen und Lieferungen von venezolanischen Arepas, erstellt mit fortschrittlichen Technologien wie Next.js 16, Neon Postgres und Drizzle ORM ArepaFlow é um sistema de pedidos e entregas de arepas venezuelanas, construído com Next.js 16, Neon Postgres e Drizzle ORM. ArepaFlow - это система заказов и доставки венесуэльских ареп, построенная на Next.js 16, Neon Postgres и Drizzle ORM. ArepaFlow هو نظامطلبات وتسليم أрепا فنزويلية، مبني على Next.js 16 و Neon Postgres و Drizzle ORM. 🍛 ArepaFlow - Dark Kitchen OS: Sistema de pedidos y entregas de arepas venezolanas. Built with Next.js 16, Neon Postgres, and Drizzle ORM. 如何使用og-image-generation 什么是og图片生成 Next.js 16教程 Neon Postgres数据库 Drizzle ORM集成 AI智能代理安装 og图片生成工具 🍛 ArepaFlow - Dark Kitchen OS: Sistema de pedidos y entregas de arepas venezolanas. Built with Next.js 16, Neon Postgres, and Drizzle ORM.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('karstenheld3/SharePoint-GPT-Middleware/session-management', 'community', 'karstenheld3', 'SharePoint-GPT-Middleware', 'karstenheld3/SharePoint-GPT-Middleware', 'session-management', 0, 0, 33, '2026-03-04T13:07:01.853Z', '2026-03-04T14:50:33.237Z', '73387388bec9e306f36c89a346e41657678b04b9870afac5bc5760499294726b', '{"id":"karstenheld3/SharePoint-GPT-Middleware/session-management","name":"session-management","description":{"zh":"一个使用 Azure Web App 和 Python 的 AI 智能代理，用于将 SharePoint 站点内容爬取到 OpenAI Vector Stores 中","ja":"Azure Web App と Python を使用した AI エージェント、SharePoint サイトのコンテンツを OpenAI Vector Stores にクロール","ko":"Azure Web App과 Python을 사용하는 AI 에이전트, SharePoint 사이트의 콘텐츠를 OpenAI Vector Stores에 크롤링","es":"Una aplicación web de Azure en Python para crawled contenido de sitios de SharePoint en tiendas de vectores de OpenAI","fr":"Une application web Azure en Python pour crawled du contenu de sites SharePoint dans des magasins de vecteurs OpenAI","de":"Eine Azure-Web-App in Python zum Crawlen von Inhalten von SharePoint-Sites in OpenAI-Vektor-Speichern","pt":"Azure Web App em Python para crawl de conteúdo de sites do SharePoint em lojas de vetores OpenAI, com gerenciamento de sessão","ru":"Azure Web App на Python для爬ления контента сайтов SharePoint в хранилища векторов OpenAI, с управлением сессиями","ar":"تطبيق ويب Azure bằng Python لاستخراج المحتوى من مواقع SharePoint إلى مخازن المتجهات مفتوحة، مع إدارة الجلسات","en":"An Azure Web App in Python to crawl the content of SharePoint sites into OpenAI Vector Stores"},"seo":{"title":{"zh":"AI智能代理：会话管理","ja":"AIエージェント：セッション管理","ko":"AI 에이전트: 세션 관리","es":"Herramientas de gestión de sesión de AI: Crawling de Shar...","fr":"Outils d''agent IA de gestion de session: Crawling de Shar...","de":"AI-Session-Management-Tools: Crawling von SharePoint mit ...","pt":"Ferramentas de IA: Gerenciamento de Sessão em Azure","ru":"ИИ Агенты: Управление Сессиями в Azure","ar":"أدوات الذكاء الاصطناعي: إدارة الجلسات في Azure","en":"session-management"},"description":{"zh":"一个使用 Azure Web App 和 Python 的 AI 智能代理，用于将 SharePoint 站点内容爬取到 OpenAI Vector Stores 中","ja":"Azure Web App と Python を使用した AI エージェント、SharePoint サイトのコンテンツを OpenAI Vector Stores にクロール","ko":"Azure Web App과 Python을 사용하는 AI 에이전트, SharePoint 사이트의 콘텐츠를 OpenAI Vector Stores에 크롤링","es":"Una aplicación web de Azure en Python para crawled contenido de sitios de SharePoint en tiendas de vectores de OpenAI","fr":"Une application web Azure en Python pour crawled du contenu de sites SharePoint dans des magasins de vecteurs OpenAI","de":"Eine Azure-Web-App in Python zum Crawlen von Inhalten von SharePoint-Sites in OpenAI-Vektor-Speichern","pt":"Azure Web App em Python para crawl de conteúdo de sites do SharePoint em lojas de vetores OpenAI, com gerenciamento de sessão","ru":"Azure Web App на Python для爬ления контента сайтов SharePoint в хранилища векторов OpenAI, с управлением сессиями","ar":"تطبيق ويب Azure bằng Python لاستخراج المحتوى من مواقع SharePoint إلى مخازن المتجهات مفتوحة، مع إدارة الجلسات","en":"An Azure Web App in Python to crawl the content of SharePoint sites into OpenAI Vector Stores"},"definition":{"en":"An Azure Web App in Python to crawl the content of SharePoint sites into OpenAI Vector Stores"},"features":{"zh":["使用 Azure Web App 和 Python","将 SharePoint 站点内容爬取到 OpenAI Vector Stores 中","支持多种数据格式","高性能和可扩展性","易于集成和部署"],"ja":["Azure Web App と Python を使用","SharePoint サイトのコンテンツを OpenAI Vector Stores にクロール","複数のデータ形式をサポート","高性能とスケーラビリティ","簡単な統合とデプロイ"],"ko":["Azure Web App과 Python을 사용","SharePoint 사이트의 콘텐츠를 OpenAI Vector Stores에 크롤링","다양한 데이터 형식을 지원","고성능과 확장성","쉽게 통합하고 배포"],"es":["Crawling de contenido de sitios de SharePoint","Almacenamiento en tiendas de vectores de OpenAI","Desarrollo con Python","Integración con Azure Web App","Gestión de sesiones de AI para optimizar el crawling"],"fr":["Crawling de contenu de sites SharePoint","Stockage dans des magasins de vecteurs OpenAI","Développement avec Python","Intégration avec Azure Web App","Gestion de sessions d''IA pour optimiser le crawling"],"de":["Crawling von Inhalten von SharePoint-Sites","Speicherung in OpenAI-Vektor-Speichern","Entwicklung mit Python","Integration mit Azure Web App","AI-Session-Management für optimiertes Crawling"],"pt":["Integração com SharePoint","Crawl de conteúdo em lojas de vetores OpenAI","Gerenciamento de sessão em Azure","Desenvolvimento em Python","Azure Web App"],"ru":["Интеграция с SharePoint","Полнотекстовый поиск контента в хранилищах векторов OpenAI","Управление сессиями в Azure","Разработка на Python","Azure Web App"],"ar":["التكامل مع SharePoint","استخراج المحتوى إلى مخازن المتجهات مفتوحة","إدارة الجلسات في Azure","التطوير باستخدام Python","تطبيق ويب Azure"]},"keywords":{"zh":["AI智能代理","会话管理","Azure Web App","Python","OpenAI Vector Stores","SharePoint","如何使用AI智能代理","AI智能代理的优点","AI智能代理的应用"],"ja":["AIエージェント","セッション管理","Azure Web App","Python","OpenAI Vector Stores","SharePoint","AIエージェントの使い方","AIエージェントの利点","AIエージェントの応用"],"ko":["AI 에이전트","세션 관리","Azure Web App","Python","OpenAI Vector Stores","SharePoint","AI 에이전트의 사용법","AI 에이전트의 장점","AI 에이전트의 응용"],"es":["herramientas de gestión de sesión de AI","crawling de sitios web","tiendas de vectores de OpenAI","desarrollo con Python","Azure Web App","gestión de sesiones de AI","cómo utilizar herramientas de gestión de sesión de AI","alternativas a herramientas de gestión de sesión de AI"],"fr":["outils d''agent IA de gestion de session","crawling de sites web","magasins de vecteurs OpenAI","développement avec Python","Azure Web App","gestion de sessions d''IA","comment utiliser des outils d''agent IA de gestion de session","alternatives aux outils d''agent IA de gestion de session"],"de":["AI-Session-Management-Tools","Crawling von Webseiten","OpenAI-Vektor-Speicher","Entwicklung mit Python","Azure Web App","AI-Session-Management","wie man AI-Session-Management-Tools verwendet","Alternativen zu AI-Session-Management-Tools"],"pt":["ferramentas de ia","gerenciamento de sessão","azure web app","python","sharepoint","openai","lojas de vetores","como usar openai","o que é gerenciamento de sessão"],"ru":["ИИ агенты","управление сессиями","azure web app","python","sharepoint","openai","хранилища векторов","как использовать openai","что такое управление сессиями"],"ar":["أدوات الذكاء الاصطناعي","إدارة الجلسات","تطبيق ويب azure","python","sharepoint","openai","مخازن المتجهات","كيفية استخدام openai","ما هي إدارة الجلسات"]}},"owner":"karstenheld3","repo":"SharePoint-GPT-Middleware","repoPath":"karstenheld3/SharePoint-GPT-Middleware","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.853Z","topics":[],"category":"community","skillMd":{"name":"session-management","description":"Apply when initializing, saving, resuming, or closing a work session","bodyPreview":"# Session Management Guide\n\n## Phase Tracking\n\nSessions track EDIRD phases:\n- NOTES.md: \"Current Phase\" section with phase, last verb, gate status\n- PROGRESS.md: \"Phase Plan\" section with 5 phases and status\n\n## MUST-NOT-FORGET\n\n- Session folder location: `[DEFAULT_SESSIONS_FOLDER]/_YYYY-MM-DD_[SessionTopicCamelCase]/`\n- Default: `[DEFAULT_SESSIONS_FOLDER]` = `[WORKSPACE_FOLDER]` (override in `!NOTES.md`)\n- Required files: NOTES.md, PROBLEMS.md, PROGRESS.md\n- Lifecycle: Init → Work → Save → Resu","body":"# Session Management Guide\n\n## Phase Tracking\n\nSessions track EDIRD phases:\n- NOTES.md: \"Current Phase\" section with phase, last verb, gate status\n- PROGRESS.md: \"Phase Plan\" section with 5 phases and status\n\n## MUST-NOT-FORGET\n\n- Session folder location: `[DEFAULT_SESSIONS_FOLDER]/_YYYY-MM-DD_[SessionTopicCamelCase]/`\n- Default: `[DEFAULT_SESSIONS_FOLDER]` = `[WORKSPACE_FOLDER]` (override in `!NOTES.md`)\n- Required files: NOTES.md, PROBLEMS.md, PROGRESS.md\n- Lifecycle: Init → Work → Save → Resume → Finalize → Archive\n- Sync session PROBLEMS.md to project on /session-finalize\n- Phase tracking: NOTES.md has current phase, PROGRESS.md has full phase plan\n- **STOP after session init**: After creating session files, STOP and wait for user review. Do NOT implement session goal until explicitly requested. User must review and refine goals before work begins.\n\n## Session Lifecycle\n\n1. **Init** (`/session-new`): Create session folder with tracking files\n2. **Work**: Create specs, plans, implement, track progress\n3. **Save** (`/session-save`): Document findings, commit changes\n4. **Resume** (`/session-load`): Re-read session documents, continue work\n5. **Finalize** (`/session-finalize`): Sync findings to project files, prepare for archive\n\n## Session Folder Location\n\n**Base:** `[DEFAULT_SESSIONS_FOLDER]` (default: `[WORKSPACE_FOLDER]`, can be overridden in `!NOTES.md`)\n\n**Format:** `[DEFAULT_SESSIONS_FOLDER]/_YYYY-MM-DD_[SessionTopicCamelCase]/`\n\n**Example:** `_PrivateSessions/_2026-01-12_FixAuthenticationBug/`\n\n## Required Session Files\n\nUse templates from this skill folder:\n\n- **NOTES.md** (`NOTES_TEMPLATE.md`): Key information, agent instructions, working patterns, large initial prompts (>120 tokens)\n- **PROBLEMS.md** (`PROBLEMS_TEMPLATE.md`): All problems to be addressed - initial prompts, questions, feature requests, bugs, strange behavior, investigation topics. Each problem gets a unique ID and tracks status (Open/Resolved/Deferred)\n- **PROGRESS.md** (`PROGRESS_TEMPLATE.md`): Task execution tracking - to-do list, done items, tried-but-not-used approaches\n\n**Key distinction:**\n- **NOTES.md** = Context and reference information (static knowledge)\n- **PROBLEMS.md** = All topics requiring attention (dynamic problem list with IDs)\n- **PROGRESS.md** = Task execution status (what''s being worked on)\n\n## Assumed Workflow\n\n```\n1. INIT: User initializes session (`/session-new`)\n   └── Session folder, NOTES.md, PROBLEMS.md, PROGRESS.md created\n\n2. PREPARE (one of):\n   A) User prepares work manually\n      └── Creates INFO / SPEC / IMPL documents, tracks progress\n   B) User explains problem, agent assists\n      └── Updates Problems, Progress, Notes → researches → creates documents\n\n3. WORK: User or agent implements\n   └── Makes decisions, creates tests, implements, verifies\n   └── Progress and findings tracked continuously\n\n4. SAVE: User saves session for later (`/session-save`)\n   └── Everything updated and committed\n\n5. RESUME: User resumes session (`/session-load`)\n   └── Agent primes from session files, executes workflows in Notes\n   └── Continue with steps 2-3\n\n6. FINALIZE: User finalizes session (`/session-finalize`)\n   └── Everything updated, committed, synced to project/workspace\n\n7. ARCHIVE: User archives session\n   └── Session folder moved to _Archive/\n```\n\n## ID System\n\nSee `[AGENT_FOLDER]/rules/devsystem-ids.md` rule (always-on) for complete ID system.\n\n**Quick Reference:**\n- Document: `[TOPIC]-[DOC][NN]` (IN, SP, IP, TP)\n  - Example: `CRWL-SP01`, `AUTH-IP01`\n- Tracking: `[TOPIC]-[TYPE]-[NNN]` (BG = Bug, FT = Feature, PR = Problem, FX = Fix, TK = Task)\n  - Example: `SAP-BG-001`, `UI-PR-003`, `GLOB-TK-015`\n- Topic Registry: Maintained in project NOTES.md\n\n## Session Init Template\n\n### NOTES.md\n```markdown\n# Session Notes\n\n## Session Info\n- **Started**: [DATE]\n- **Goal**: [Brief description]\n\n## Key Decisions\n\n## Important Findings\n\n## Workflows to Run on Resume\n```\n\n### PROBLEMS.md\n```markdown\n# Session Problems\n\n## Open\n\n## Resolved\n\n## Deferred\n```\n\n### PROGRESS.md\n```markdown\n# Session Progress\n\n## To Do\n\n## In Progress\n\n## Done\n\n## Tried But Not Used\n```\n"},"lastSynced":"2026-03-04T14:50:33.237Z","agentAnalysis":{"suitability":{"en":"Ideal for Azure-focused AI Agents requiring structured session tracking and phase management in Python","zh":"适用于需要在Python中进行结构化会话跟踪和阶段管理的Azure专注AI代理的理想选择","ja":"Pythonで構造化されたセッションの追跡とフェーズ管理を必要とするAzureに特化したAIエージェントに最適","ko":"Python에서 구조화된 세션 추적 및 단계 관리가 필요한 Azure에 중점을 둔 AI 에이전트에 적합","es":"Ideal para agentes de inteligencia artificial enfocados en Azure que requieren un seguimiento de sesión estructurado y gestión de fases en Python","fr":"Idéal pour les agents d''intelligence artificielle axés sur Azure nécessitant un suivi de session structuré et une gestion de phases en Python","de":"Ideal für Azure-fokussierte KI-Agenten, die ein strukturiertes Sitzungs-Tracking und Phasenmanagement in Python erfordern","pt":"Ideal para Agentes de IA focados no Azure que necessitam de rastreamento de sessão estruturado e gerenciamento de fases em Python","ru":"Идеально для агентов ИИ, ориентированных на Azure, требующих структурированного отслеживания сессий и управления фазами в Python","ar":"مثالية للوكلاء الذكاء الاصطناعي المتمحورة حول Azure التي تتطلب تتبع جلسة منظم وإدارة مرحلة في Python"},"recommendation":{"en":"Empowers agents to efficiently track EDIRD phases, manage session folders, and interact with OpenAI Vector Stores using Azure Web Apps, while maintaining comprehensive content analysis through NOTES.md, PROBLEMS.md, and PROGRESS.md files","zh":"赋予代理高效地跟踪EDIRD阶段、管理会话文件夹、使用Azure Web Apps与OpenAI Vector Stores交互的能力，同时通过NOTES.md、PROBLEMS.md和PROGRESS.md文件保持全面内容分析","ja":"EDIRDフェーズの追跡、セッションフォルダの管理、Azure Web Appsを使用したOpenAI Vector Storesとの相互作用を効率的に行い、NOTES.md、PROBLEMS.md、PROGRESS.mdファイルを介した包括的なコンテンツ分析を維持するエージェントをEmpowerする","ko":"EDIRD 단계를 추적하고, 세션 폴더를 관리하며, Azure Web Apps를 사용하여 OpenAI Vector Stores와 상호 작용하는 에이전트를 능력화하여 NOTES.md, PROBLEMS.md 및 PROGRESS.md 파일을 통해 포괄적인 콘텐츠 분석을 유지","es":"Permite a los agentes realizar un seguimiento eficiente de las fases de EDIRD, gestionar carpetas de sesión e interactuar con OpenAI Vector Stores mediante Azure Web Apps, manteniendo al mismo tiempo un análisis de contenido integral a través de archivos NOTES.md, PROBLEMS.md y PROGRESS.md","fr":"Permet aux agents de suivre efficacement les phases EDIRD, de gérer les dossiers de session et d''interagir avec OpenAI Vector Stores à l''aide d''Azure Web Apps, tout en maintenant une analyse complète de contenu via les fichiers NOTES.md, PROBLEMS.md et PROGRESS.md","de":"Ermöglicht es Agenten, EDIRD-Phasen effizient zu verfolgen, Sitzungsordner zu verwalten und mit OpenAI Vector Stores über Azure Web Apps zu interagieren, während sie gleichzeitig eine umfassende Inhaltsanalyse durch NOTES.md-, PROBLEMS.md- und PROGRESS.md-Dateien aufrechterhalten","pt":"Habilita os agentes a rastrear eficientemente as fases EDIRD, gerenciar pastas de sessão e interagir com OpenAI Vector Stores usando Azure Web Apps, mantendo uma análise de conteúdo abrangente por meio de arquivos NOTES.md, PROBLEMS.md e PROGRESS.md","ru":"Позволяет агентам эффективно отслеживать фазы EDIRD, управлять папками сессий и взаимодействовать с OpenAI Vector Stores с помощью Azure Web Apps, сохраняя комплексный анализ содержания с помощью файлов NOTES.md, PROBLEMS.md и PROGRESS.md","ar":"تمكين الوكلاء من تتبع مراحل EDIRD بفعالية وإدارة مجلدات الجلسة والتفاعل مع OpenAI Vector Stores باستخدام Azure Web Apps ، مع الحفاظ على تحليل شامل للمحتوى من خلال ملفات NOTES.md و PROBLEMS.md و PROGRESS.md"},"useCases":{"en":["Tracking EDIRD phases for project management","Automating session folder creation and organization","Integrating OpenAI Vector Stores for enhanced content analysis"],"zh":["用于项目管理的EDIRD阶段跟踪","自动化会话文件夹的创建和组织","将OpenAI Vector Stores集成到增强的内容分析中"],"ja":["プロジェクト管理のためのEDIRDフェーズの追跡","セッションフォルダの作成と組織の自動化","強化されたコンテンツ分析のためのOpenAI Vector Storesの統合"],"ko":["프로젝트 관리를 위한 EDIRD 단계 추적","세션 폴더 생성 및 조직 자동화","콘텐츠 분석 강화를 위한 OpenAI Vector Stores 통합"],"es":["Seguimiento de fases de EDIRD para la gestión de proyectos","Automatización de la creación y organización de carpetas de sesión","Integración de OpenAI Vector Stores para un análisis de contenido mejorado"],"fr":["Suivi des phases EDIRD pour la gestion de projet","Automatisation de la création et de l''organisation des dossiers de session","Intégration de OpenAI Vector Stores pour une analyse de contenu améliorée"],"de":["Verfolgung von EDIRD-Phasen für das Projektmanagement","Automatisierung der Erstellung und Organisation von Sitzungsordnern","Integration von OpenAI Vector Stores für eine verbesserte Inhaltsanalyse"],"pt":["Rastreamento de fases EDIRD para gerenciamento de projetos","Criação e organização automática de pastas de sessão","Integração de OpenAI Vector Stores para análise de conteúdo aprimorada"],"ru":["Отслеживание фаз EDIRD для управления проектами","Автоматизированная создание и организация папок сессий","Интеграция OpenAI Vector Stores для расширенного анализа содержания"],"ar":["تتبع مراحل EDIRD لإدارة المشاريع","إنشاء وتنظيم مجلدات الجلسة تلقائيًا","دمج OpenAI Vector Stores لتحليل المحتوى المحسّن"]},"limitations":{"en":["Requires Azure Web App setup","Python environment necessary","Dependent on OpenAI Vector Stores and SharePoint site access"],"zh":["需要Azure Web App设置","需要Python环境","依赖于OpenAI Vector Stores和SharePoint站点访问"],"ja":["Azure Web Appのセットアップが必要","Python環境が必要","OpenAI Vector StoresとSharePointサイトへのアクセスに依存"],"ko":["Azure Web App 설정이 필요","Python 환경이 필요","OpenAI Vector Stores 및 SharePoint 사이트 액세스에 의존"],"es":["Requiere configuración de Azure Web App","Entorno de Python necesario","Dependiente de OpenAI Vector Stores y acceso al sitio de SharePoint"],"fr":["Nécessite une configuration d''Azure Web App","Environnement Python nécessaire","Dépendant de OpenAI Vector Stores et d''un accès au site SharePoint"],"de":["Benötigt Azure Web App-Setup","Python-Umgebung erforderlich","Abhängig von OpenAI Vector Stores und SharePoint-Seitenzugriff"],"pt":["Requer configuração do Azure Web App","Ambiente Python necessário","Dependente de OpenAI Vector Stores e acesso ao site do SharePoint"],"ru":["Требуется настройка Azure Web App","Необходимо окружение Python","Зависит от OpenAI Vector Stores и доступа к сайту SharePoint"],"ar":["يتطلب إعداد Azure Web App","بيئة Python ضرورية","يعتمد على OpenAI Vector Stores ووصول إلى موقع SharePoint"]},"version":3},"contentHash":"73387388bec9e306f36c89a346e41657678b04b9870afac5bc5760499294726b","qualityScore":33}');
