INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CleanExpo/Unite-Hub/decision-moment-skill', 'decision-moment-skill', 'CleanExpo', 'Unite-Hub', 'community', 'decision-moment-skill CleanExpo Unite-Hub community decision-moment-skill是Unite Group CRM中的AI智能决策工具，帮助开发者做出更好的决策 decision-moment-skillはUnite Group CRMのAIエージェント機能で、開発者の意思決定を支援します decision-moment-skill은 Unite Group CRM의 AI 에이전트 기능으로 개발자의 의사결정을 지원합니다 Unite Group CRM es una plataforma que se integra con decision-moment-skill para mejorar la toma de decisiones con herramientas de IA Unite Group CRM est une plateforme qui s''intègre à decision-moment-skill pour améliorer la prise de décision avec des outils d''IA Unite Group CRM ist eine Plattform, die sich mit decision-moment-skill integriert, um die Entscheidungsfindung mit KI-Tools zu verbessern O decision-moment-skill é uma habilidade de IA que otimiza o Unite Group CRM para desenvolvedores, melhorando a tomada de decisões Decision-moment-skill - это навык ИИ, который оптимизирует Unite Group CRM для разработчиков, улучшая процесс принятия решений decision-moment-skill هو مهارة ذكاء اصطناعي تحسن من Unite Group CRM للمطورين، وتحسين عملية اتخاذ القرارات Unite Group CRM 如何使用AI智能决策工具 什么是AI智能决策 Unite Group CRM替代品 decision-moment-skill安装 AI智能决策工具设置指南 Unite Group CRM vs Competitor Unite Group CRM');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heyAyushh/gloves/deslop', 'community', 'heyAyushh', 'gloves', 'heyAyushh/gloves', 'deslop', 0, 0, 33, '2026-02-27T13:08:04.220Z', '2026-02-27T14:10:46.930Z', '931d9baf60c69db6a51a1d32775ab80eb67ff8a7038428ad1bfc94f87acfa515', '{"id":"heyAyushh/gloves/deslop","name":"deslop","description":{"zh":"Deslop AI智能代理是一款使用OpenCLAW的凭证和密码管理工具，提供安全审计功能","ja":"Deslop AIエージェントはOpenCLAWを使用した資格情報とパスワードマネージャーです","ko":"Deslop AI 에이전트는 OpenCLAW를 사용하여 자격 증명 및 암호를 관리하고 보안 감사를 제공하는 도구입니다","es":"Deslop es un gestor de credenciales y contraseñas con auditorías para humanos y agentes de IA. Proporciona una forma segura de gestionar tus datos","fr":"Deslop est un gestionnaire de credentials et de mots de passe avec audits pour humains et agents d''IA. Il offre une façon sécurisée de gérer vos données","de":"Deslop ist ein Credential- und Passwort-Manager mit Audits für Menschen und KI-Agents. Es bietet eine sichere Möglichkeit, Ihre Daten zu verwalten","pt":"O Deslop é um gerenciador de credenciais e senhas com auditorias para humanos e agentes, projetado para melhorar a segurança e a eficiência","ru":"Deslop - менеджер учетных данных и паролей с аудитом для людей и ИИ Агентов, предназначенный для улучшения безопасности и эффективности","ar":"Deslop هو مدير بيانات الاعتماد وكلمات المرور مع تدقيق للبشر وآلات الإي الأجنت، مصمم لتحسين الأمان والكفاءة","en":"openclaw credentials and passwords manager with audits for humans and agents."},"seo":{"title":{"zh":"Deslop AI智能代理：OpenCLAW凭证和密码管理","ja":"Deslop AIエージェント：OpenCLAW資格情報とパスワードマネージャー","ko":"Deslop AI 에이전트: OpenCLAW 자격 증명 및 암호 관리자","es":"Deslop: Gestor de credenciales y contraseñas con auditorí...","fr":"Deslop: Gestionnaire de credentials et de mots de passe a...","de":"Deslop: Credential- und Passwort-Manager mit Audits für M...","pt":"Deslop: Gerenciador de Credenciais e Senhas com Auditoria...","ru":"Deslop: Менеджер учетных данных и паролей с аудитом для И...","ar":"Deslop: مدير بيانات الاعتماد وكلمات المرور مع التدقيق لآل...","en":"deslop"},"description":{"zh":"Deslop AI智能代理是一款使用OpenCLAW的凭证和密码管理工具，提供安全审计功能","ja":"Deslop AIエージェントはOpenCLAWを使用した資格情報とパスワードマネージャーです","ko":"Deslop AI 에이전트는 OpenCLAW를 사용하여 자격 증명 및 암호를 관리하고 보안 감사를 제공하는 도구입니다","es":"Deslop es un gestor de credenciales y contraseñas con auditorías para humanos y agentes de IA. Proporciona una forma segura de gestionar tus datos","fr":"Deslop est un gestionnaire de credentials et de mots de passe avec audits pour humains et agents d''IA. Il offre une façon sécurisée de gérer vos données","de":"Deslop ist ein Credential- und Passwort-Manager mit Audits für Menschen und KI-Agents. Es bietet eine sichere Möglichkeit, Ihre Daten zu verwalten","pt":"O Deslop é um gerenciador de credenciais e senhas com auditorias para humanos e agentes, projetado para melhorar a segurança e a eficiência","ru":"Deslop - менеджер учетных данных и паролей с аудитом для людей и ИИ Агентов, предназначенный для улучшения безопасности и эффективности","ar":"Deslop هو مدير بيانات الاعتماد وكلمات المرور مع تدقيق للبشر وآلات الإي الأجنت، مصمم لتحسين الأمان والكفاءة","en":"openclaw credentials and passwords manager with audits for humans and agents."},"definition":{"en":"openclaw credentials and passwords manager with audits for humans and agents."},"features":{"zh":["OpenCLAW凭证管理","密码管理","安全审计","多用户支持","CLI接口"],"ja":["OpenCLAW資格情報管理","パスワード管理","セキュリティ監査","マルチユーザーサポート","CLIインターフェース"],"ko":["OpenCLAW 자격 증명 관리","암호 관리","보안 감사","다중 사용자 지원","CLI 인터페이스"],"es":["Gestión de credenciales y contraseñas","Auditorías para humanos y agentes de IA","Protección de datos con OpenCLAW","Soporte para múltiples plataformas","Integración con herramientas de desarrollo"],"fr":["Gestion de credentials et de mots de passe","Audits pour humains et agents d''IA","Protection des données avec OpenCLAW","Support pour plusieurs plateformes","Intégration avec des outils de développement"],"de":["Verwaltung von Credentials und Passwörtern","Audits für Menschen und KI-Agents","DatenSchutz mit OpenCLAW","Unterstützung für mehrere Plattformen","Integration mit Entwicklungstools"],"pt":["Gerenciamento de credenciais e senhas","Recursos de auditoria para humanos e agentes","Integração com OpenCLAW","Segurança e eficiência melhoradas","Suporte para desenvolvedores e agentes de IA"],"ru":["Управление учетными данными и паролями","Функции аудита для людей и ИИ Агентов","Интеграция с OpenCLAW","Улучшенная безопасность и эффективность","Поддержка разработчиков и ИИ Агентов"],"ar":["إدارة بيانات الاعتماد وكلمات المرور","ميزات التدقيق للبشر وآلات الإي الأجنت","التكامل مع OpenCLAW","أمان وكفاءة محسنة","دعم مطوري وآلات الإي الأجنت"]},"keywords":{"zh":["Deslop AI智能代理","OpenCLAW凭证管理","密码管理工具","安全审计软件","如何使用Deslop","Deslop与其他工具比较"],"ja":["Deslop AIエージェント","OpenCLAW資格情報管理","パスワードマネージャー","セキュリティ監査ツール","Deslopの使い方","Deslopと他のツールの比較"],"ko":["Deslop AI 에이전트","OpenCLAW 자격 증명 관리","암호 관리 도구","보안 감사 소프트웨어","Deslop 사용 방법","Deslop과 다른 도구 비교"],"es":["cómo usar Deslop","qué es la gestión de credenciales","Deslop alternativa","Deslop vs LastPass","instalar Deslop","guía de configuración de Deslop"],"fr":["comment utiliser Deslop","quoi est la gestion de credentials","Deslop alternative","Deslop vs LastPass","installer Deslop","guide de configuration de Deslop"],"de":["wie man Deslop verwendet","was ist Credential-Management","Deslop Alternative","Deslop vs LastPass","Deslop installieren","Deslop-Konfigurationsanleitung"],"pt":["como usar Deslop","o que é Deslop","Deslop alternativa","Deslop vs outros gerenciadores","instalar Deslop","guia de configuração do Deslop","Deslop para desenvolvedores","Deslop para agentes de IA"],"ru":["как использовать Deslop","что такое Deslop","Deslop альтернатива","Deslop vs другие менеджеры","установить Deslop","руководство по настройке Deslop","Deslop для разработчиков","Deslop для ИИ Агентов"],"ar":["كيفية استخدام Deslop","ما هو Deslop","بديل Deslop","Deslop مقابل أدوات أخرى","تثبيت Deslop","دليل إعداد Deslop","Deslop للمطورين","Deslop لآلات الإي الأجنت"]}},"owner":"heyAyushh","repo":"gloves","repoPath":"heyAyushh/gloves","stars":0,"forks":0,"updatedAt":"2026-02-27T13:08:04.220Z","topics":[],"category":"community","skillMd":{"name":"deslop","description":"Remove AI-generated code slop and improve code quality. Use when you need to clean up AI-written code, remove unnecessary defensive patterns, eliminate inconsistent comments, or align code style with the rest of the codebase.","bodyPreview":"# Remove AI Code Slop\n\nCheck the diff against main and remove AI-generated slop from this branch.\n\nIf the diff is empty and on main/master, scan the entire codebase for AI slop.\n\n## What to Remove\n\n- Extra comments that a human wouldn''t add or inconsistent with the file\n- Unnecessary defensive checks or try/catch blocks abnormal for that codebase area (especially if called by trusted/validated codepaths)\n- Casts to `any` to work around type issues\n- Any style inconsistent with the file\n\n## Outpu","body":"# Remove AI Code Slop\n\nCheck the diff against main and remove AI-generated slop from this branch.\n\nIf the diff is empty and on main/master, scan the entire codebase for AI slop.\n\n## What to Remove\n\n- Extra comments that a human wouldn''t add or inconsistent with the file\n- Unnecessary defensive checks or try/catch blocks abnormal for that codebase area (especially if called by trusted/validated codepaths)\n- Casts to `any` to work around type issues\n- Any style inconsistent with the file\n\n## Output\n\nReport with only a 1-3 sentence summary of what was changed.\n"},"lastSynced":"2026-02-27T14:10:46.930Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced AI-generated code cleanup capabilities.","zh":"非常适合需要高级 AI 生成代码清理功能的代码审查代理。","ja":"コードレビュー エージェントが高度な AI 生成コードのクリーンアップ機能を必要とする場合に最適です。","ko":"고급 AI 생성 코드 정리 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades avanzadas de limpieza de código generadas por IA.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de nettoyage de code avancées générées par l''IA.","de":"Perfekt für Code-Review-Agents, die erweiterte AI-generierte Code-Reinigungsfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades avançadas de limpeza de código gerado por IA.","ru":"Идеально подходит для агентов код-ревью, которым необходимы продвинутые возможности очистки кода, сгенерированного ИИ.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى إمكانيات متقدمة لتنظيف الكود الذي تم إنشاؤه بواسطة الذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to remove AI-generated slop from codebases using OpenCLAW credentials and password audits, by eliminating extra comments, unnecessary defensive checks, and inconsistent coding styles, ensuring consistency with the file''s style and improving overall code quality.","zh":"赋予代理使用 OpenCLAW 凭证和密码审计，从代码库中删除 AI 生成的杂乱代码，通过消除额外的注释、不必要的防御性检查和不一致的编码风格，确保与文件风格的一致性并提高整体代码质量。","ja":"OpenCLAW 資格情報とパスワード監査を使用して、コードベースから AI 生成の不要なコードを削除し、余分なコメント、不要な防御的チェック、不一致なコーディングスタイルを排除し、ファイルのスタイルとの一致性を確保し、全体的なコード品質を向上させることで、エージェントをEmpowerします。","ko":"OpenCLAW 자격 정보와 비밀번호 감사를 사용하여 코드베이스에서 AI 생성된 불필요한 코드를 제거하고,额外한 주석, 불필요한 방어적 확인, 일관되지 않은 코딩 스타일을 제거하여 파일의 스타일과 일관성을 보장하고, 전체적인 코드 품질을 향상 시켜 에이전트를 강화합니다.","es":"Habilita a los agentes a eliminar la porquería generada por la IA de los conjuntos de código utilizando credenciales de OpenCLAW y auditorías de contraseñas, eliminando comentarios adicionales, comprobaciones defensivas innecesarias y estilos de codificación inconsistentes, garantizando la coherencia con el estilo del archivo y mejorando la calidad general del código.","fr":"Permet aux agents d''éliminer les saletés générées par l''IA des bases de code en utilisant les informations d''identification OpenCLAW et les audits de mots de passe, en éliminant les commentaires supplémentaires, les vérifications défensives inutiles et les styles de codage incohérents, en garantissant la cohérence avec le style du fichier et en améliorant la qualité globale du code.","de":"Ermächtigt Agenten, die von der künstlichen Intelligenz generierte Unordnung aus Codebasen zu entfernen, indem OpenCLAW-Zugangsdaten und Passwortaudits verwendet werden, um zusätzliche Kommentare, unnötige Abwehrprüfungen und inkonsistente Codierungsstile zu eliminieren und so die Konsistenz mit dem Stil der Datei sicherzustellen und die allgemeine Codequalität zu verbessern.","pt":"Habilita os agentes a removerem o lixo gerado por IA dos repositórios de código usando credenciais OpenCLAW e auditorias de senhas, eliminando comentários extras, verificações defensivas desnecessárias e estilos de codificação inconsistentes, garantindo a consistência com o estilo do arquivo e melhorando a qualidade geral do código.","ru":"Наделяет агентов возможностью удалять мусор, сгенерированный ИИ, из кодобаз, используя учетные данные OpenCLAW и аудиты паролей, путем устранения лишних комментариев, ненужных защитных проверок и несоответствующих стилей кодирования, обеспечивая соответствие стилю файла и повышая общее качество кода.","ar":"يمنح العميل القدرة على إزالة الفوضى التي تم إنشاؤها بواسطة الذكاء الاصطناعي من قواعد البيانات باستخدام أوراق اعتماد OpenCLAW ومراجعة كلمات المرور ، من خلال إزالة التعليقات الإضافية والتحقق الدفاعي غير الضروري والأسلوب غير المتسق من الترميز ، مما يضمن الاتساق مع نمط الملف وتحسين جودة الكود بشكل عام."},"useCases":{"en":["Scanning entire codebases for AI-generated slop","Removing unnecessary try/catch blocks and defensive checks","Enforcing consistent coding styles across the codebase"],"zh":["扫描整个代码库以查找 AI 生成的杂乱代码","删除不必要的 try/catch 块和防御性检查","在代码库中强制执行一致的编码风格"],"ja":["AI 生成の不要なコードを検索するためにコードベース全体をスキャンする","不要な try/catch ブロックと防御的チェックを削除する","コードベース全体で一貫したコーディングスタイルを適用する"],"ko":["AI 생성된 불필요한 코드를 검색하기 위해 전체 코드베이스를 스캔한다","불필요한 try/catch 블록과 방어적 확인을 제거한다","코드베이스 전체에서 일관된 코딩 스타일을 적용한다"],"es":["Escaneo de conjuntos de código completos en busca de porquería generada por la IA","Eliminación de bloques try/catch y comprobaciones defensivas innecesarias","Aplicación de estilos de codificación coherentes en todo el conjunto de código"],"fr":["Analyse de bases de code complètes à la recherche de saletés générées par l''IA","Suppression de blocs try/catch et de vérifications défensives inutiles","Application de styles de codage cohérents dans l''ensemble de la base de code"],"de":["Scannen von Codebasen auf von der künstlichen Intelligenz generierte Unordnung","Entfernen unnötiger try/catch-Blöcke und Abwehrprüfungen","Durchsetzen von konsistenten Codierungsstilen im gesamten Codebase"],"pt":["Digitalização de todo o repositório de código em busca de lixo gerado por IA","Remoção de blocos try/catch e verificações defensivas desnecessárias","Aplicação de estilos de codificação consistentes em todo o repositório de código"],"ru":["Сканирование всего кодобаза на наличие мусора, сгенерированного ИИ","Удаление ненужных блоков try/catch и защитных проверок","Применение последовательных стилей кодирования во всем кодобазе"],"ar":["فحص قاعدة البيانات بأكملها بحثًا عن الفوضى التي تم إنشاؤها بواسطة الذكاء الاصطناعي","إزالة كتل Try / Catch والتحقق الدفاعي غير الضروري","تطبيق أسلوب الترميز المتسق عبر قاعدة البيانات بأكملها"]},"limitations":{"en":["Requires access to codebase diffs and main/master branches","Limited to codebases with consistent style guidelines"],"zh":["需要访问代码库的差异和主/主分支","仅限于具有一致样式指南的代码库"],"ja":["コードベースの差分とメイン/マスター ブランチへのアクセスが必要","一貫したスタイル ガイドラインを持つコードベースのみに限定される"],"ko":["코드베이스의 차이 및 메인/마스터 브랜치에 대한 액세스가 필요하다","일관된 스타일 가이드ライン을 갖춘 코드베이스에만 제한된다"],"es":["Requiere acceso a diffs de codebase y ramas main/master","Limitado a codebases con directrices de estilo coherentes"],"fr":["Nécessite l''accès aux diffs de base de code et aux branches main/master","Limité aux bases de code avec des lignes directrices de style cohérentes"],"de":["Benötigt Zugriff auf Codebase-Diffs und main/master-Zweige","Begrenzt auf Codebasen mit konsistenten Stilrichtlinien"],"pt":["Requer acesso às diferenças do repositório de código e às branches main/master","Limitado a repositórios de código com diretrizes de estilo consistentes"],"ru":["Требует доступа к разностям кодобаза и основным веткам master","Ограничен кодобазами с последовательными руководствами по стилю"],"ar":["يتطلب الوصول إلى 差异ات قاعدة البيانات وفرع رئيسي / رئيسي","محدود بقواعد البيانات التي لديها إرشادات نمط متسقة"]},"version":3},"contentHash":"931d9baf60c69db6a51a1d32775ab80eb67ff8a7038428ad1bfc94f87acfa515","qualityScore":33}');
