INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CofficLab/GitOK/i18n-translate', 'i18n-translate', 'CofficLab', 'GitOK', 'community', 'i18n-translate CofficLab GitOK community git swift swiftui i18n-translate是一个综合项目管理工具，支持git和swift开发 i18n-translateは、プロジェクト管理を支援する包括的なツールです i18n-translate는 프로젝트 관리를 지원하는 포괄적인 도구입니다 La herramienta de traducción i18n es una herramienta de gestión de proyectos integral para desarrolladores L''outil de traduction i18n est un outil de gestion de projet complet pour les développeurs Das I18n-Übersetzungstool ist ein umfassendes Projektmanagement-Tool für Entwickler A ferramenta i18n-translate é uma solução abrangente para gerenciamento de projetos de desenvolvimento, com suporte a git, swift e swiftui ИИ Агенты: i18n-translate, комплексный инструмент для управления разработкой проектов с поддержкой git, swift и swiftui أداة الترجمة i18n-translate هي حل شامل لإدارة مشاريع البرمجة، بدعم ل git و swift و swiftui A comprehensive project management tool 如何使用i18n-translate 什么是i18n-translate i18n-translate替代品 i18n-translate安装 i18n-translate设置指南 git版本控制 swift开发 swiftui开发 A comprehensive project management tool');
