INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pcortellezzi/rs_trader/doc', 'doc', 'pcortellezzi', 'rs_trader', 'community', 'doc pcortellezzi rs_trader community doc技能是AI智能代理平台，用于优化代码管理和提高开发效率 docプラットフォームはAIエージェントを使用した開発効率向上とコード管理の最適化を実現 doc 플랫폼은 AI 에이전트를 사용하여 개발 효율성을 높이고 코드 관리를 최적화 La plataforma de trading con tecnología de AI Doc ofrece operaciones avanzadas y personalizadas La plateforme de trading avec technologie d''IA Doc propose des opérations avancées et personnalisées Die Trading-Plattform mit KI-Technologie Doc bietet erweiterte und personalisierte Operationen A plataforma de negociação é uma ferramenta de Inteligência Artificial para desenvolvedores que buscam melhorar suas habilidades de negociação. Торговая платформа - это инструмент ИИ для разработчиков, которые хотят улучшить свои навыки торговли. منصة التداول هي أداة ذكاء اصطناعي للمطورين الذين يبحثون عن تحسين مهاراتهم في التداول. Tarding Platform AI智能代理 代码管理 开发效率 doc技能 AI工具 如何使用AI智能代理 代码管理最佳实践 开发效率提高方法 AI智能代理平台 代码管理平台 Tarding Platform');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anasahmed07/doit/minikube', 'community', 'anasahmed07', 'doit', 'anasahmed07/doit', 'minikube', 0, 0, 31, '2026-03-01T12:47:24.853Z', '2026-03-01T14:38:48.159Z', 'f409094ab18876d8c9e56e445b1d8bf812d8cfd75b534451c9efaba1b6827d68', '{"id":"anasahmed07/doit/minikube","name":"minikube","description":{"zh":"Minikube是Kubernetes的本地开发工具，else它将被安排永远困扰你","ja":"MinikubeはKubernetesのローカル開発ツールで、elseそれをスケジュールして永遠に悩まされる","ko":"Minikube는 Kubernetes의 로컬 개발 도구입니다. else 그것을 예약하면 영원히 괴롭히게 됩니다","es":"minikube es una herramienta de desarrollo que ayuda a los desarrolladores a evitar problemas de programación","fr":"minikube est un outil de développement qui aide les développeurs à éviter les problèmes de programmation","de":"minikube ist ein Entwicklungstool, das Entwicklern hilft, Programmierprobleme zu vermeiden","pt":"O Minikube é uma ferramenta de IA que ajuda os desenvolvedores a gerenciar suas aplicações, evitando problemas futuros","ru":"Minikube - это инструмент ИИ, который помогает разработчикам управлять своими приложениями, избегая будущих проблем","ar":"Minikube هي أداة ذكاء اصطناعي تساعد المطورين على إدارة تطبيقاتهم، وتجنب المشاكل المستقبلية","en":"else it will be sheduled to haunt you forever."},"seo":{"title":{"zh":"Minikube AIエージェント工具","ja":"Minikube AIエージェントの使い方","ko":"Minikube AI 에이전트 설치 가이드","es":"Herramientas de AI: minikube para desarrolladores","fr":"Outils d''IA: minikube pour les développeurs","de":"KI-Tools: minikube für Entwickler","pt":"Ferramentas de IA: Minikube","ru":"ИИ Агенты: Minikube","ar":"أدوات الذكاء الاصطناعي: Minikube","en":"minikube"},"description":{"zh":"Minikube是Kubernetes的本地开发工具，else它将被安排永远困扰你","ja":"MinikubeはKubernetesのローカル開発ツールで、elseそれをスケジュールして永遠に悩まされる","ko":"Minikube는 Kubernetes의 로컬 개발 도구입니다. else 그것을 예약하면 영원히 괴롭히게 됩니다","es":"minikube es una herramienta de desarrollo que ayuda a los desarrolladores a evitar problemas de programación","fr":"minikube est un outil de développement qui aide les développeurs à éviter les problèmes de programmation","de":"minikube ist ein Entwicklungstool, das Entwicklern hilft, Programmierprobleme zu vermeiden","pt":"O Minikube é uma ferramenta de IA que ajuda os desenvolvedores a gerenciar suas aplicações, evitando problemas futuros","ru":"Minikube - это инструмент ИИ, который помогает разработчикам управлять своими приложениями, избегая будущих проблем","ar":"Minikube هي أداة ذكاء اصطناعي تساعد المطورين على إدارة تطبيقاتهم، وتجنب المشاكل المستقبلية","en":"else it will be sheduled to haunt you forever."},"definition":{"en":"else it will be sheduled to haunt you forever."},"features":{"zh":["支持本地Kubernetes开发","运行和测试容器化应用","支持多种容器运行时","易于安装和配置","支持Kubernetes的所有功能"],"ja":["ローカルKubernetes開発をサポート","コンテナ化アプリケーションの実行とテスト","複数のコンテナランタイムをサポート","簡単なインストールと設定","Kubernetesのすべての機能をサポート"],"ko":["로컬 Kubernetes 개발 지원","컨테이너화된 애플리케이션 실행 및 테스트","다중 컨테이너 런타임 지원","쉬운 설치 및 구성","Kubernetes의 모든 기능 지원"],"es":["Entorno de desarrollo local","Soporte para Kubernetes","Facilidad de uso","Flexibilidad en la configuración","Integración con otros herramientas de desarrollo"],"fr":["Environnement de développement local","Prise en charge de Kubernetes","Facilité d''utilisation","Flexibilité de configuration","Intégration avec d''autres outils de développement"],"de":["Lokale Entwicklungsumgebung","Unterstützung für Kubernetes","Einfachheit der Bedienung","Flexibilität bei der Konfiguration","Integration mit anderen Entwicklungstools"],"pt":["Gerenciamento de aplicações","Prevenção de problemas futuros","Integração com ferramentas de desenvolvimento","Suporte a múltiplos ambientes","Facilidade de uso"],"ru":["Управление приложениями","Предотвращение будущих проблем","Интеграция с инструментами разработки","Поддержка нескольких сред","Легкость использования"],"ar":["إدارة التطبيقات","تجنب المشاكل المستقبلية","التكامل مع أدوات التطوير","دعم بيئات متعددة","سهولة الاستخدام"]},"keywords":{"zh":["Minikube安装","Kubernetes本地开发","容器化应用开发","Minikube vs KIND","如何使用Minikube","Minikube教程","Kubernetes开发工具"],"ja":["Minikubeのインストール","Kubernetesローカル開発","コンテナ化アプリケーション開発","Minikube vs KIND","Minikubeの使い方","Minikubeチュートリアル","Kubernetes開発ツール"],"ko":["Minikube 설치","Kubernetes 로컬 개발","컨테이너화된 애플리케이션 개발","Minikube vs KIND","Minikube 사용법","Minikube 튜토리얼","Kubernetes 개발 도구"],"es":["minikube","herramientas de AI","desarrollo de Kubernetes","entorno de desarrollo local","cómo usar minikube","minikube vs kubernetes","instalación de minikube","guía de configuración de minikube"],"fr":["minikube","outils d''IA","développement Kubernetes","environnement de développement local","comment utiliser minikube","minikube vs kubernetes","installation de minikube","guide de configuration de minikube"],"de":["minikube","KI-Tools","Kubernetes-Entwicklung","lokale Entwicklungsumgebung","wie man minikube verwendet","minikube vs kubernetes","installation von minikube","konfigurationsanleitung für minikube"],"pt":["como usar Minikube","o que é Minikube","Minikube alternativa","Minikube vs Kubernetes","instalar Minikube","guia de configuração do Minikube","desenvolvimento de aplicações com Minikube"],"ru":["как использовать Minikube","что такое Minikube","альтернативы Minikube","Minikube vs Kubernetes","установка Minikube","руководство по настройке Minikube","разработка приложений с Minikube"],"ar":["كيفية استخدام Minikube","ما هي Minikube","بديل Minikube","Minikube مقابل Kubernetes","تثبيت Minikube","دليل إعداد Minikube","تطوير التطبيقات مع Minikube"]}},"owner":"anasahmed07","repo":"doit","repoPath":"anasahmed07/doit","stars":0,"forks":0,"updatedAt":"2026-03-01T12:47:24.853Z","topics":[],"category":"community","skillMd":{"name":"minikube","description":"Manages local Kubernetes clusters using Minikube for development and testing. This skill should be used when setting up local K8s environments, enabling addons, configuring networking, and deploying applications locally. Use this skill for Phase IV local Kubernetes deployments before cloud deployment.","bodyPreview":"# Minikube Skill\n\n## Overview\n\nMinikube runs a single-node Kubernetes cluster locally for development and testing. It supports multiple container runtimes (Docker, containerd, CRI-O) and provides easy addon management.\n\n## Installation\n\n### macOS\n```bash\n# Homebrew\nbrew install minikube\n\n# Or direct download\ncurl -LO https://storage.googleapis.com/minikube/releases/latest/minikube-darwin-arm64\nsudo install minikube-darwin-arm64 /usr/local/bin/minikube\n```\n\n### Linux\n```bash\ncurl -LO https://stor","body":"# Minikube Skill\n\n## Overview\n\nMinikube runs a single-node Kubernetes cluster locally for development and testing. It supports multiple container runtimes (Docker, containerd, CRI-O) and provides easy addon management.\n\n## Installation\n\n### macOS\n```bash\n# Homebrew\nbrew install minikube\n\n# Or direct download\ncurl -LO https://storage.googleapis.com/minikube/releases/latest/minikube-darwin-arm64\nsudo install minikube-darwin-arm64 /usr/local/bin/minikube\n```\n\n### Linux\n```bash\ncurl -LO https://storage.googleapis.com/minikube/releases/latest/minikube-linux-amd64\nsudo install minikube-linux-amd64 /usr/local/bin/minikube\n```\n\n### Windows (WSL2)\n```bash\ncurl -LO https://storage.googleapis.com/minikube/releases/latest/minikube-linux-amd64\nsudo install minikube-linux-amd64 /usr/local/bin/minikube\n```\n\n## Essential Commands\n\n### Cluster Management\n\n```bash\n# Start cluster (uses Docker driver by default)\nminikube start\n\n# Start with specific resources\nminikube start --memory=8192 --cpus=4\n\n# Start with specific Kubernetes version\nminikube start --kubernetes-version=v1.28.0\n\n# Start with specific driver\nminikube start --driver=docker\n\n# Check cluster status\nminikube status\n\n# Stop cluster (preserves state)\nminikube stop\n\n# Delete cluster completely\nminikube delete\n\n# Delete all clusters and profiles\nminikube delete --all\n```\n\n### Multiple Profiles\n\n```bash\n# Create named cluster\nminikube start -p my-cluster\n\n# Switch between clusters\nminikube profile my-cluster\n\n# List all profiles\nminikube profile list\n\n# Delete specific profile\nminikube delete -p my-cluster\n```\n\n### Accessing the Cluster\n\n```bash\n# Open Kubernetes dashboard\nminikube dashboard\n\n# Get cluster IP\nminikube ip\n\n# SSH into the node\nminikube ssh\n\n# Access service via URL\nminikube service <service-name> --url\n\n# Open service in browser\nminikube service <service-name>\n```\n\n## Addons\n\nMinikube addons extend cluster functionality:\n\n### List and Enable Addons\n\n```bash\n# List all available addons\nminikube addons list\n\n# Enable addon\nminikube addons enable <addon-name>\n\n# Disable addon\nminikube addons disable <addon-name>\n```\n\n### Essential Addons for TaskFlow\n\n```bash\n# Ingress controller (REQUIRED for external access)\nminikube addons enable ingress\n\n# Ingress DNS (optional, for local DNS)\nminikube addons enable ingress-dns\n\n# Metrics server (for kubectl top)\nminikube addons enable metrics-server\n\n# Dashboard (web UI)\nminikube addons enable dashboard\n\n# Storage provisioner (for PVCs)\nminikube addons enable storage-provisioner\n\n# Registry (local container registry)\nminikube addons enable registry\n```\n\n### Full Setup for TaskFlow\n\n```bash\n# Start with sufficient resources\nminikube start --memory=8192 --cpus=4\n\n# Enable essential addons\nminikube addons enable ingress\nminikube addons enable metrics-server\nminikube addons enable storage-provisioner\nminikube addons enable dashboard\n```\n\n## Networking\n\n### Accessing Services\n\nThree ways to access services in Minikube:\n\n#### 1. NodePort Service\n```bash\n# Get service URL\nminikube service my-service --url\n# Returns: http://192.168.49.2:30080\n```\n\n#### 2. Minikube Tunnel (LoadBalancer)\n```bash\n# Run in separate terminal (requires sudo)\nminikube tunnel\n\n# Now LoadBalancer services get external IPs\nkubectl get svc\n# EXTERNAL-IP will show actual IP instead of <pending>\n```\n\n#### 3. Port Forwarding\n```bash\nkubectl port-forward svc/my-service 8080:80\n# Access at http://localhost:8080\n```\n\n### Ingress Setup\n\n```bash\n# Enable ingress addon\nminikube addons enable ingress\n\n# Get minikube IP\nminikube ip\n# Returns: 192.168.49.2\n\n# Add to /etc/hosts\necho \"$(minikube ip) taskflow.local\" | sudo tee -a /etc/hosts\n\n# Now access via: http://taskflow.local\n```\n\n## Using Local Docker Images\n\n### Load Image into Minikube\n\n```bash\n# Load from local Docker\nminikube image load my-image:tag\n\n# List images in Minikube\nminikube image list\n```\n\n### Build Directly in Minikube\n\n```bash\n# Point Docker CLI to Minikube''s Docker daemon\neval $(minikube docker-env)\n\n# Now docker build goes directly into Minikube\ndocker build -t my-app:local .\n\n# Use imagePullPolicy: Never in K8s manifests\n```\n\n### Reset Docker Environment\n\n```bash\n# Return to local Docker daemon\neval $(minikube docker-env -u)\n```\n\n## Configuration\n\n### Set Default Memory/CPU\n\n```bash\nminikube config set memory 8192\nminikube config set cpus 4\nminikube config set driver docker\n```\n\n### View Configuration\n\n```bash\nminikube config view\n```\n\n## Debugging\n\n### Logs\n\n```bash\n# Minikube logs\nminikube logs\n\n# Follow logs\nminikube logs -f\n\n# Specific component logs\nminikube logs --file=kubelet\n```\n\n### Common Issues\n\n#### 1. Insufficient Resources\n```bash\n# Stop and restart with more resources\nminikube stop\nminikube start --memory=8192 --cpus=4\n```\n\n#### 2. Driver Issues\n```bash\n# Try different driver\nminikube delete\nminikube start --driver=docker\n```\n\n#### 3. Ingress Not Working\n```bash\n# Verify ingress addon is running\nkubectl get pods -n ingress-nginx\n\n# Check ingress controller logs\nkubectl logs -n ingress-nginx -l app.kubernetes.io/component=controller\n```\n\n#### 4. Services Not Accessible\n```bash\n# Check if tunnel is needed\nminikube tunnel  # Run in separate terminal\n\n# Or use NodePort\nminikube service <service-name>\n```\n\n## TaskFlow Deployment Workflow\n\n```bash\n# 1. Start Minikube\nminikube start --memory=8192 --cpus=4\n\n# 2. Enable addons\nminikube addons enable ingress\nminikube addons enable metrics-server\n\n# 3. Point to Minikube Docker\neval $(minikube docker-env)\n\n# 4. Build images locally\ndocker build -t taskflow/api:local ./packages/api\ndocker build -t taskflow/web:local ./web-dashboard\ndocker build -t taskflow/sso:local ./sso-platform\ndocker build -t taskflow/mcp-server:local ./packages/mcp-server\n\n# 5. Deploy with Helm\nhelm install taskflow ./helm/taskflow \\\n  --set api.image.tag=local \\\n  --set api.image.pullPolicy=Never \\\n  --set web.image.tag=local \\\n  --set web.image.pullPolicy=Never\n\n# 6. Start tunnel for LoadBalancer\nminikube tunnel\n\n# 7. Access application\nminikube service taskflow-web\n```\n\n## Quick Reference\n\n| Command | Purpose |\n|---------|---------|\n| `minikube start` | Start cluster |\n| `minikube stop` | Stop cluster |\n| `minikube delete` | Delete cluster |\n| `minikube status` | Check status |\n| `minikube dashboard` | Open web UI |\n| `minikube addons list` | List addons |\n| `minikube service <svc>` | Access service |\n| `minikube tunnel` | Enable LoadBalancer |\n| `minikube ip` | Get cluster IP |\n| `minikube image load <img>` | Load Docker image |\n| `eval $(minikube docker-env)` | Use Minikube Docker |\n\n## Resources\n\nRefer to `references/addons-guide.md` for detailed addon configurations.\n"},"lastSynced":"2026-03-01T14:38:48.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Native Agents needing local Kubernetes development and testing capabilities.","zh":"非常适合需要本地Kubernetes开发和测试能力的云原生代理。","ja":"クラウドネイティブエージェントがローカルでKubernetes開発とテストを行う必要がある場合に最適です。","ko":"로컬 쿠버네티스 개발 및 테스트 기능이 필요한 클라우드 네이티브 에이전트에게 최적입니다.","es":"Perfecto para agentes nativos de la nube que necesitan capacidades de desarrollo y prueba de Kubernetes locales.","fr":"Parfait pour les agents Cloud Native nécessitant des capacités de développement et de test Kubernetes locales.","de":"Perfekt für Cloud Native Agents, die lokale Kubernetes-Entwicklungs- und Testfunktionen benötigen.","pt":"Perfeito para Agentes Nativos em Nuvem que precisam de capacidades de desenvolvimento e teste do Kubernetes local.","ru":"Идеально подходит для облачных агентов, которым необходимы локальные возможности разработки и тестирования Kubernetes.","ar":"مثالي لعميل الأجهزة الوكيل السحابي الذي يحتاج إلى إمكانيات التطوير والاختبار المحلية لكوبيرنيتس"},"recommendation":{"en":"Empowers agents to run single-node Kubernetes clusters locally, supporting multiple container runtimes like Docker, containerd, and CRI-O, and providing easy addon management through protocols like HTTPS.","zh":"赋予代理运行单节点Kubernetes集群的能力，支持多种容器运行时，如Docker、containerd和CRI-O，并通过HTTPS等协议提供易于管理的插件。","ja":"エージェントがシングルノードKubernetesクラスターをローカルで実行できるようにし、Docker、containerd、CRI-Oなどの複数のコンテナランタイムをサポートし、HTTPSなどのプロトコルを介してアドオンの管理を容易に行える。","ko":"에이전트가 로컬에서 단일 노드 쿠버네티스 클러스터를 실행할 수 있도록 하며 Docker, containerd, CRI-O 등을 포함한 여러 컨테이너 런타임을 지원하며 HTTPS 등 프로토콜을 통해 애드온 관리를 쉽게 제공합니다.","es":"Habilita a los agentes a ejecutar clústeres de Kubernetes de un solo nodo de forma local, admitiendo varios tiempos de ejecución de contenedores como Docker, containerd y CRI-O, y proporcionando una administración de complementos fácil a través de protocolos como HTTPS.","fr":"Permet aux agents d''exécuter des clusters Kubernetes à nœud unique en local, prenant en charge plusieurs runtime de conteneurs tels que Docker, containerd et CRI-O, et fournissant une gestion facile des modules complémentaires via des protocoles comme HTTPS.","de":"Ermöglicht es Agents, einzelnodiige Kubernetes-Cluster lokal auszuführen, mehrere Container-Laufzeiten wie Docker, containerd und CRI-O zu unterstützen und eine einfache Verwaltung von Addons über Protokolle wie HTTPS bereitzustellen.","pt":"Permite que os agentes executem clusters Kubernetes de um único nó localmente, suportando vários tempos de execução de contêiner, como Docker, containerd e CRI-O, e fornecendo gerenciamento fácil de complementos por meio de protocolos como HTTPS.","ru":"Позволяет агентам запускать однозадочные кластеры Kubernetes локально, поддерживая несколько контейнерных сред выполнения, таких как Docker, containerd и CRI-O, и обеспечивая простое управление дополнениями через протоколы, такие как HTTPS.","ar":"يمكن للوكيل تشغيل مجموعات كوبيرنيتس من عقدة واحدة محليًا ، ودعم عدة أوقات تشغيل الحاويات مثل Docker و containerd و CRI-O ، وتوفير إدارة إضافات سهلة عبر بروتوكولات مثل HTTPS"},"useCases":{"en":["Deploying microservices for local testing","Debugging Kubernetes configurations","Developing and testing cloud native applications"],"zh":["部署微服务进行本地测试","调试Kubernetes配置","开发和测试云原生应用程序"],"ja":["マイクロサービスをローカルテスト用にデプロイする","Kubernetes構成のデバッグ","クラウドネイティブアプリケーションの開発とテスト"],"ko":["로컬 테스트를 위한 마이크로 서비스 배포","쿠버네티스 구성 디버깅","클라우드 네이티브 애플리케이션 개발 및 테스트"],"es":["Implementación de microservicios para pruebas locales","Depuración de configuraciones de Kubernetes","Desarrollo y prueba de aplicaciones nativas de la nube"],"fr":["Déploiement de microservices pour des tests locaux","Débogage des configurations Kubernetes","Développement et test d''applications cloud natives"],"de":["Bereitstellung von Microservices für lokale Tests","Fehlerbehebung bei Kubernetes-Konfigurationen","Entwicklung und Testen von Cloud-Native-Anwendungen"],"pt":["Implantação de microsserviços para teste local","Depuração de configurações do Kubernetes","Desenvolvimento e teste de aplicações nativas em nuvem"],"ru":["Развертывание микросервисов для локального тестирования","Отладка конфигураций Kubernetes","Разработка и тестирование облачных родных приложений"],"ar":["نشر ميكروسيرفيسات للاختبار المحلي","تصحيح أخطاء تكوينات كوبيرنيتس","تطوير واختبار تطبيقات الأجهزة الوكيل السحابي"]},"limitations":{"en":["Requires administrative privileges for installation","Limited to single-node clusters","Dependent on container runtime availability"],"zh":["需要管理员权限进行安装","仅限单节点集群","依赖容器运行时的可用性"],"ja":["インストールには管理者権限が必要","シングルノードクラスターのみ","コンテナランタイムの可用性に依存"],"ko":["설치에는 관리자 권한이 필요함","단일 노드 클러스터로 제한됨","컨테이너 런타임 가용성에 의존"],"es":["Requiere privilegios administrativos para la instalación","Limitado a clústeres de un solo nodo","Dependiente de la disponibilidad del tiempo de ejecución del contenedor"],"fr":["Nécessite des privilèges administratifs pour l''installation","Limité aux clusters à nœud unique","Dépend de la disponibilité du runtime de conteneur"],"de":["Benötigt administrative Rechte für die Installation","Begrenzt auf einzelnodiige Cluster","Abhängig von der Verfügbarkeit der Container-Laufzeit"],"pt":["Requer privilégios administrativos para instalação","Limitado a clusters de um único nó","Dependente da disponibilidade do tempo de execução do contêiner"],"ru":["Требует административных привилегий для установки","Ограничен однозадочными кластерами","Зависит от доступности контейнерной среды выполнения"],"ar":["يتطلب امتيازات إدارية للتثبيت","محدود بمجموعات عقدة واحدة","يت phụ على توافر وقت تشغيل الحاويات"]},"version":3},"contentHash":"f409094ab18876d8c9e56e445b1d8bf812d8cfd75b534451c9efaba1b6827d68","qualityScore":31}');
