INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('johnlindquist/script-kit-next/script-kit-logging', 'script-kit-logging', 'johnlindquist', 'script-kit-next', 'community', 'script-kit-logging johnlindquist script-kit-next community Script Kit Logging是使用Rust和GPUI重写的高性能脚本工具，用于提高开发效率 Script Kit LoggingはRustとGPUIを使用して再設計された高性能スクリプトツールで、開発の効率化を実現します 스크립트 키트 로깅은 러스트와 GPUI를 사용하여 다시 작성된 고성능 스크립트 도구로 개발 효율성을 높입니다 Script Kit Logging es una herramienta de AI reescrita en Rust utilizando GPUI, ideal para desarrolladores que buscan una solución de registro eficiente Script Kit Logging est un outil d''IA réécrit en Rust en utilisant GPUI, idéal pour les développeurs qui recherchent une solution de journalisation efficace Script Kit Logging ist ein KI-Tool, das in Rust mit GPUI umgeschrieben wurde, ideal für Entwickler, die eine effiziente Protokolllösung suchen O Script Kit Logging é uma ferramenta de IA reescrita em Rust com GPUI, oferecendo uma solução eficiente para desenvolvedores. ИИ Агент Script Kit Logging - это инструмент, переписанный на Rust с использованием GPUI, предлагающий эффективное решение для разработчиков. أداة الذكاء الاصطناعي Script Kit Logging هي أداة مُعاد كتابة بلغة Rust باستخدام GPUI، وتقدم حلًا فعالًا للمطورين. Script Kit rewritten in Rust using GPUI (Zed''s UI framework) 如何使用Script Kit Logging 什么是Script Kit Logging Script Kit Logging替代品 Script Kit Logging与其他工具的比较 Script Kit Logging安装指南 Script Kit Logging设置教程 Rust开发工具 GPUI集成 Script Kit rewritten in Rust using GPUI (Zed''s UI framework)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PackmindHub/coding-agents-matrix/add-agent-property', 'community', 'PackmindHub', 'coding-agents-matrix', 'PackmindHub/coding-agents-matrix', 'add-agent-property', 0, 0, 31, '2026-03-04T13:07:01.683Z', '2026-03-04T13:25:25.350Z', 'b171e1ed50c61dc1d99688e641ac098e4e8cdff5fab210d57b14204c541506b9', '{"id":"PackmindHub/coding-agents-matrix/add-agent-property","name":"add-agent-property","description":{"zh":"add-agent-property是一种AI工具比较矩阵，帮助开发者选择最合适的AI工具","ja":"add-agent-propertyはAIエージェントの比較マトリックスであり、開発者が最も適切なAIエージェントを選択するのに役立ちます","ko":"add-agent-property는 AI 에이전트 비교 매트릭스로서 개발자가 가장 적합한 AI 에이전트를 선택하는 데 도움이 됩니다","es":"La matriz de comparación de agentes de codificación AI es una herramienta curada para desarrolladores. add-agent-property ofrece una visión general clara de las opciones de codificación AI","fr":"La matrice de comparaison des agents de codage IA est un outil répertorié pour les développeurs. add-agent-property offre une vue d''ensemble claire des options de codage IA","de":"Die Vergleichsmatrix für AI-Coding-Agenten ist ein kuratiertes Tool für Entwickler. add-agent-property bietet eine klare Übersicht über die AI-Coding-Optionen","pt":"Nossa matriz de comparação de agentes de IA ajuda a escolher a melhor ferramenta para o seu projeto","ru":"Наша сравнительная матрица ИИ Агентов помогает выбрать лучший инструмент для вашего проекта","ar":"مصفوفة المقارنة الخاصة بنا لوكلاء الذكاء الاصطناعي تساعد في اختيار أفضل أداة لمشروعك","en":"A curated comparison matrix of ai coding agents"},"seo":{"title":{"zh":"AI工具比较：add-agent-property","ja":"AIエージェント比較：add-agent-property","ko":"AI 에이전트 비교: add-agent-property","es":"Comparativa de agentes de codificación AI: add-agent-prop...","fr":"Outil de comparaison des agents de codage IA: add-agent-p...","de":"Vergleichsmatrix für AI-Coding-Agenten: add-agent-property","