INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ConnerBabb/Instapermit/secure-pr', 'secure-pr', 'ConnerBabb', 'Instapermit', 'community', 'secure-pr ConnerBabb Instapermit community Instapermit安全审查是AIエージェント安全的重要组成部分，用于确保代码安全性和合规性 InstapermitのセキュアなPRは、AIエージェントの安全性を確保するための重要なコンポーネントです Instapermit 보안审查는 AI 에이전트의 보안성을 확보하기 위한 중요한 구성 요소입니다 Instapermit con secure-pr es una herramienta de AI que permite mejorar la seguridad en proyectos de desarrollo Instapermit avec secure-pr est un outil d''IA qui permet d''améliorer la sécurité dans les projets de développement Instapermit mit secure-pr ist ein KI-Tool, das die Sicherheit in Entwicklungsprojekten verbessert O Instapermit com secure-pr é uma ferramenta de IA que ajuda a melhorar a segurança do código. Ele oferece recursos avançados para proteger seu código Instapermit с secure-pr - это инструмент ИИ Агентов, который помогает повысить безопасность кода. Он предлагает расширенные функции для защиты вашего кода Instapermit مع secure-pr هو أداة ذكاء اصطناعي تساعد على تحسين أمان kod. يقدم ميزات متقدمة لحماية kodك Instapermit 如何使用Instapermit 什么是AIエージェント安全审查 Instapermit替代品 Instapermit与其他安全工具的比较 Instapermit安装指南 Instapermit设置教程 AIエージェント安全最佳实践 Instapermit');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('arbgjr/satra/reference-indexer', 'community', 'arbgjr', 'satra', 'arbgjr/satra', 'reference-indexer', 0, 0, 31, '2026-03-04T13:07:01.691Z', '2026-03-04T13:32:53.719Z', 'd4d5d7f829d7f6f8873f64aacbc96b74e6b0cb34b4eaafbb73d5ae23589886d4', '{"id":"arbgjr/satra/reference-indexer","name":"reference-indexer","description":{"zh":"reference-indexer是一个实时监控B3资产波动的AI智能代理，帮助开发者快速发现市场机会","ja":"reference-indexerはB3資産のボラティリティをリアルタイムに監視するAIエージェントで、開発者が市場の機会を迅速に発見するのに役立ちます","ko":"reference-indexer는 B3 자산 변동성을 실시간으로 모니터링하는 AI 에이전트로 개발자가 시장 기회를 신속하게 발견하는 데 도움이 됩니다","es":"reference-indexer es un sistema de alertas en tiempo real para volatilidad de ativos de la B3, diseñado para desarrolladores que necesitan monitorear el mercado","fr":"reference-indexer est un système d''alertes en temps réel pour la volatilité des actifs de la B3, conçu pour les développeurs qui doivent surveiller le marché","de":"reference-indexer ist ein Echtzeit-Alertsystem für B3-Volatilität, entwickelt für Entwickler, die den Markt überwachen müssen","pt":"O reference-indexer é uma ferramenta de IA que fornece alertas em tempo real para volatilidade de ativos da B3, ajudando desenvolvedores a tomar decisões informadas.","ru":"Reference-indexer - это инструмент ИИ, который предоставляет реальные уведомления о волатильности активов B3, giúpая разработчикам принимать обоснованные решения.","ar":"أداة الذكاء الاصطناعي reference-indexer توفر تنبيهات في الوقت الفعلي لتقلبات الأسهم في B3، مما يساعد المطورين على اتخاذ قرارات مستنيرة.","en":"Sistema de alertas em tempo real para volatilidade de ativos da B3"},"seo":{"title":{"zh":"AI智能代理_reference-indexer实时监控B3资产波动","ja":"AIエージェント_reference-indexerでB3資産のボラティリティをリアルタイムに監視","ko":"AI 에이전트_reference-indexer B3 자산 변동성 실시간 모니터링","es":"Herramientas de IA: reference-indexer para volatilidad de...","fr":"Outils d''IA : r