INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eqtylab/real-a2a/ralph2ralph', 'ralph2ralph', 'eqtylab', 'real-a2a', 'community', 'ralph2ralph eqtylab real-a2a community ralph2ralph是一种基于p2p技术的AI智能代理，能够帮助开发者轻松构建高性能的应用 ralph2ralphはp2p技術を基盤とするAIエージェントで、開発者が高性能なアプリケーションを簡単に構築できる ralph2ralph는 p2p 기술 기반의 AI 에이전트로 개발자가 고성능의 애플리케이션을 쉽게 구축할 수 있도록 도와줍니다 ralph2ralph es una herramienta de IA que se basa en la tecnología p2p para ofrecer soluciones innovadoras y eficientes ralph2ralph est un outil d''IA qui repose sur la technologie p2p pour offrir des solutions innovantes et efficaces ralph2ralph ist ein KI-Tool, das auf p2p-Technologie basiert, um innovative und effiziente Lösungen anzubieten O ralph2ralph é uma ferramenta de IA que simplifica a comunicação p2p, tornando-a mais eficiente e escalável. Com o lema ''p2p é tudo o que você precisa'', essa tecnologia inovadora está mudando a forma como desenvolvedores trabalham. Ralph2ralph - это ИИ Агент, который упрощает p2p, делая его более эффективным и масштабируемым. С девизом ''p2p всё, что вам нужно'', эта инновационная технология меняет то, как разработчики работают. ralph2ralph هو أداة ذكاء اصطناعي تبسط الاتصال من نقطة إلى نقطة، مما يجعله أكثر كفاءة ومتانة. مع شعار ''p2p كل ما تحتاجه''، هذه التكنولوجيا المبتكرة تغير الطريقة التي يعمل بها المطورون. p2p is all you need ralph2ralph教程 p2p技术介绍 AI智能代理比较 ralph2ralph安装 高性能数据处理 ralph2ralph vs 其他AI工具 p2p is all you need');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nehemiaharchives/lucene-kmp/port', 'community', 'nehemiaharchives', 'lucene-kmp', 'nehemiaharchives/lucene-kmp', 'port', 0, 0, 31, '2026-03-04T13:07:01.740Z', '2026-03-04T14:05:15.177Z', '1eef80d15f1f7c982b9e0d5b0efe2b19ec32435694d71cb3452e5a11d8b70bed', '{"id":"nehemiaharchives/lucene-kmp/port","name":"port","description":{"zh":"Apache Lucene port是Kotlin Multiplatform的搜索引擎库，用于提升搜索功能。","ja":"Apache Lucene portは、Kotlin Multiplatform用の検索エンジンライブラリです。","ko":"Apache Lucene port는 Kotlin Multiplatform용 검색 엔진 라이브러리입니다.","es":"El puerto Apache Lucene para Kotlin Multiplatform permite a los desarrolladores crear aplicaciones más eficientes y escalables. Conoce más sobre esta herramienta de IA","fr":"Le port Apache Lucene pour Kotlin Multiplatform permet aux développeurs de créer des applications plus efficaces et évolutives. En savoir plus sur cet outil IA","de":"Der Apache Lucene-Port für Kotlin Multiplatform ermöglicht es Entwicklern, effizientere und skalierbare Anwendungen zu erstellen. Erfahren Sie mehr über dieses KI-Tool","pt":"O port Apache Lucene para Kotlin Multiplatform é uma ferramenta de IA que permite a criação de aplicações de busca eficientes","ru":"Порт Apache Lucene для Kotlin Multiplatform - это инструмент ИИ, который позволяет создавать эффективные приложения поиска","ar":"منفذ Apache Lucene لكوتلين متعددة المنصات هو أداة ذكاء اصطناعي تتيح إنشاء تطبيقات بحث فعالة","en":"[WIP] Apache Lucene port for Kotlin Multiplatform"},"seo":{"title":{"zh":"AI智能工具：Kotlin Multiplatform版Apache Lucene port","ja":"AIエージェント：Kotlin Multiplatform用Apache Lucene port","ko":"AI 에이전트: Kotlin Multiplatform용 Apache Lucene port","es":"Herramientas de IA: Puerto Apache Lucene para Kotlin Mult...","fr":"Outils IA: Port Apache Lucene pour Kotlin Multiplatform","de":"KI-Tools: Apache Lucene-Port für Kotlin Multiplatform","pt":"F