INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryokun6/ryos/localize', 'localize', 'ryokun6', 'ryos', 'community', 'localize ryokun6 ryos community ryOS是基于Cursor的AI智能代理本地化解决方案，提供简单易用的开发体验 ryOSはCursorベースのAIエージェントのローカライズソリューションで、シンプルで使いやすい開発体験を提供します ryOS는 Cursor 기반의 AI 에이전트 현지화 솔루션으로, 단순하고 사용하기 쉬운 개발 환경을 제공합니다 ryOS, hecho con Cursor, es una herramienta de localización para desarrolladores que necesitan adaptar sus aplicaciones a diferentes regiones ryOS, réalisé avec Cursor, est un outil de localisation pour les développeurs qui ont besoin d''adapter leurs applications à différentes régions ryOS, erstellt mit Cursor, ist ein Lokalisierungstool für Entwickler, die ihre Anwendungen an verschiedene Regionen anpassen müssen O ryOS, feito com Cursor, é uma ferramenta de IA que oferece funcionalidades de localize para desenvolvedores ИИ Агент ryOS, созданный с помощью Cursor, предлагает функции localize для разработчиков أداة الذكاء الاصطناعي ryOS، التي تم إنشاؤها مع Cursor، توفر ميزات localize للمطورين ryOS, made with Cursor AI智能代理 本地化解决方案 Cursor技术 如何使用ryOS AI代理技术 多语言支持 高性能AI计算 ryOS, made with Cursor');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blockmatic/basilic/ahooks', 'community', 'blockmatic', 'basilic', 'blockmatic/basilic', 'ahooks', 0, 0, 31, '2026-03-04T13:07:01.795Z', '2026-03-04T14:27:55.191Z', '3619a1d5c301136fecc3ca74d2cee8141e56e9ddf581957df92667bd894b257b', '{"id":"blockmatic/basilic/ahooks","name":"ahooks","description":{"zh":"ahooks是FullStack Web3和AI项目的启动器，帮助开发者快速构建和部署应用","ja":"ahooksはFullStack Web3とAIプロジェクトのスターターで、開発者が迅速にアプリケーションを構築してデプロイできるようにします","ko":"ahooks는 FullStack Web3와 AI 프로젝트의 시작기로 개발자가 빠르게 애플리케이션을 구축하고 배포할 수 있도록 도와줍니다","es":"ahooks es un iniciador de proyectos Web3 y AI que permite a los desarrolladores crear aplicaciones full-stack con facilidad","fr":"ahooks est un initiateur de projets Web3 et IA qui permet aux développeurs de créer des applications full-stack avec facilité","de":"ahooks ist ein Projektstarter für Web3- und KI-Anwendungen, der es Entwicklern ermöglicht, full-stack-Anwendungen einfach zu erstellen","pt":"A ferramenta de inteligência artificial ahooks é um projeto de inteligência artificial que visa ajudar a criar projetos web3 mais eficientes e escaláveis.","ru":"ИИ Агент ahooks - это проект ИИ, который направлен на помощь созданию проектов web3 более эффективных и масштабных.","ar":"أداة إنجليزية للاستقاءة للاجứng web3 هي مشروع إنجليزية للاستقاءة للاجứng web3 الذي يهدف إلى مساعدة في создать проекты web3 أكثر كفاءة وscalability.","en":"FullStack Web3 & AI Project Starter"},"seo":{"title":{"zh":"ahooks AI智能工具 - FullStack Web3 项目启动器","ja":"ahooks AIエージェント - FullStack Web3 プロジェクトスターター","ko":"ahooks AI 에이전트 - FullStack Web3 프로젝트 시작기","es":"ahooks: Herramientas de AI para proyectos Web3","fr":"ahooks: Outils d''IA pour les projets Web3","de":"ahooks: KI-Tools für Web3-Projekte","pt":"ahooks - Ferramenta de inteligência artificial para proje...","ru":"ahooks - ИИ Агент для проектов web3","ar":"ahooks - أد